<template>
  <div class="shop-page">
    <!-- 1) Barra de anuncio -->
    <div class="announcement">Envíos a toda Colombia · Mínimo 6 unidades por pedido</div>

    <!-- 2) Header sticky -->
    <header class="header" :class="{ 'header--scrolled': scrolled }">
      <div class="container-x">
        <div class="header__inner">
          <div
            class="header__brand"
            :class="{ 'header__brand--link': productId }"
            @click="productId && goBack()"
          >
            <img
              v-if="logoSrc && !logoFailed"
              :src="logoSrc"
              alt="Logo"
              class="header__logo"
              @error="logoFailed = true"
            />
            <img v-else :src="logoFallback" alt="Logo" class="header__logo" />
            <span class="header__name">{{ nombreTienda }}</span>
          </div>

          <label class="header__search">
            <i class="fas fa-search header__search-icon"></i>
            <input
              v-model="search"
              type="text"
              class="header__search-input"
              placeholder="Buscar"
            />
            <button
              v-if="search"
              class="header__search-clear"
              aria-label="Limpiar búsqueda"
              @click="search = ''"
            >
              <i class="fas fa-times"></i>
            </button>
          </label>

          <button
            class="header__menu"
            aria-label="Ver categorías"
            @click="catMenuOpen = true"
          >
            <i class="fas fa-bars"></i>
          </button>
          <button class="header__cart" aria-label="Ver carrito" @click="openCart">
            <i class="fas fa-shopping-bag"></i>
            <span v-if="cartCount > 0" class="header__cart-bubble">{{ cartBubble }}</span>
          </button>
        </div>

        <div class="header__row2">
          <label class="header__search header__search--mobile">
            <i class="fas fa-search header__search-icon"></i>
            <input
              v-model="search"
              type="text"
              class="header__search-input"
              placeholder="Buscar"
            />
            <button
              v-if="search"
              class="header__search-clear"
              aria-label="Limpiar búsqueda"
              @click="search = ''"
            >
              <i class="fas fa-times"></i>
            </button>
          </label>
        </div>
      </div>
    </header>

    <!-- Banners a todo el ancho (imagen PC / celular, carrusel si hay más de uno) -->
    <section
      v-if="banners.length"
      v-show="!productId && !search.trim()"
      class="banner"
      @mouseenter="stopBannerTimer"
      @mouseleave="startBannerTimer"
      @touchstart.passive="onBannerTouchStart"
      @touchend="onBannerTouchEnd"
    >
      <div class="banner__track">
        <picture
          v-for="(b, i) in banners"
          :key="'bn' + i"
          class="banner__slide"
          :class="{ 'banner__slide--active': i === bannerPos }"
        >
          <source v-if="b.mobile && b.desktop" media="(max-width: 749px)" :srcset="resolveImagen(b.mobile)" />
          <img :src="resolveImagen(b.desktop || b.mobile)" alt="Promoción" />
        </picture>
      </div>
      <template v-if="banners.length > 1">
        <button class="gal-arrow gal-arrow--prev" aria-label="Banner anterior" @click="bannerStep(-1)">
          <i class="fas fa-chevron-left"></i>
        </button>
        <button class="gal-arrow gal-arrow--next" aria-label="Banner siguiente" @click="bannerStep(1)">
          <i class="fas fa-chevron-right"></i>
        </button>
        <div class="pcard__dots">
          <button
            v-for="(b, i) in banners"
            :key="'bd' + i"
            class="pcard__dot"
            :class="{ 'pcard__dot--active': i === bannerPos }"
            :aria-label="'Banner ' + (i + 1)"
            @click="goBanner(i)"
          ></button>
        </div>
      </template>
    </section>

    <!-- 3) Colección: se oculta (no se destruye) al ver un producto para volver a la misma posición -->
    <main v-show="!productId" class="collection">
      <div class="container-x">
        <div class="collection__head">
          <h1>Catálogo Mayorista</h1>
          <p v-if="vendedorNombre">
            Atendido por <strong>{{ vendedorNombre }}</strong> · Pedidos por WhatsApp
          </p>
        </div>

        <!-- 4) Toolbar -->
        <div ref="toolbar" class="toolbar">
          <span class="toolbar__count">{{ productosFiltrados.length }} producto{{ productosFiltrados.length === 1 ? '' : 's' }}</span>
          <label class="toolbar__sort">
            <span class="toolbar__label">Ordenar por</span>
            <span class="select-wrap">
              <select v-model="sortBy">
                <option value="destacados">Destacados</option>
                <option value="az">Alfabéticamente A–Z</option>
                <option value="za">Z–A</option>
                <option value="precio_asc">Precio menor a mayor</option>
                <option value="precio_desc">Precio mayor a menor</option>
                <option value="stock">Mayor stock</option>
              </select>
              <i class="fas fa-chevron-down"></i>
            </span>
          </label>
        </div>

        <!-- 5) Chips de categorías (las flechas indican que hay más hacia ese lado) -->
        <div v-if="categorias.length" class="cat-chips-wrap">
          <button
            v-show="chipsCanLeft"
            class="cat-chips-arrow cat-chips-arrow--prev"
            aria-label="Ver categorías anteriores"
            @click="scrollChips(-1)"
          ><span><i class="fas fa-chevron-left"></i></span></button>
          <div ref="chips" class="cat-chips" @wheel="onChipsWheel" @scroll.passive="updateChipsArrows">
            <button
              class="cat-chip"
              :class="{ 'cat-chip--active': activeCat === null }"
              @click="activeCat = null"
            >
              Todas
            </button>
            <button
              v-for="cat in categorias"
              :key="cat.id"
              class="cat-chip"
              :class="{ 'cat-chip--active': activeCat === cat.id }"
              @click="activeCat = cat.id"
            >
              {{ cat.label }}
            </button>
          </div>
          <button
            v-show="chipsCanRight"
            class="cat-chips-arrow cat-chips-arrow--next"
            aria-label="Ver más categorías"
            @click="scrollChips(1)"
          ><span><i class="fas fa-chevron-right"></i></span></button>
        </div>

        <!-- 7) Estado de carga -->
        <div v-if="loading" class="pgrid">
          <div v-for="n in 8" :key="'sk-' + n" class="pcard skeleton">
            <div class="skeleton__media"></div>
            <div class="skeleton__line" style="width: 40%"></div>
            <div class="skeleton__line" style="width: 80%"></div>
            <div class="skeleton__line" style="width: 25%"></div>
          </div>
        </div>

        <!-- 7) Estado de error -->
        <div v-else-if="error" class="shop-state">
          <i class="fas fa-exclamation-circle shop-state__icon"></i>
          <p>Ocurrió un error al cargar el catálogo.</p>
          <button class="shop-state__link" @click="cargarCatalogo">Reintentar</button>
        </div>

        <!-- 7) Estado vacío -->
        <div v-else-if="productosFiltrados.length === 0" class="shop-state">
          <i class="fas fa-search shop-state__icon"></i>
          <p>No se encontraron productos</p>
          <button class="shop-state__link" @click="limpiarFiltros">Limpiar búsqueda</button>
        </div>

        <!-- 6) Grilla de productos: la tarjeta abre el detalle del producto -->
        <div v-else class="pgrid">
          <article
            v-for="p in productosFiltrados"
            :key="p.matid"
            class="pcard"
            @click="abrirProducto(p)"
          >
            <div class="pcard__media" @mousemove="onZoomMove" @mouseleave="onZoomLeave">
              <transition name="slidefade" mode="out-in">
                <img
                  v-if="fotoActual(p)"
                  :key="fotoActual(p)"
                  :src="fotoActual(p)"
                  :alt="p.descrip"
                  :class="{ 'img-pending': !isImgLoaded(fotoActual(p)) }"
                  loading="lazy"
                  @load="onImgLoad(fotoActual(p))"
                  @error="onFotoError(p)"
                />
                <i v-else class="fas fa-tshirt pcard__placeholder"></i>
              </transition>
              <span v-if="fotoActual(p) && !isImgLoaded(fotoActual(p))" class="img-spinner"></span>

              <!-- Carrusel: flechas y puntos -->
              <template v-if="fotosVivas(p).length > 1">
                <button
                  class="pcard__arrow pcard__arrow--prev"
                  aria-label="Foto anterior"
                  @click.stop="pasarFoto(p, -1)"
                ><i class="fas fa-chevron-left"></i></button>
                <button
                  class="pcard__arrow pcard__arrow--next"
                  aria-label="Foto siguiente"
                  @click.stop="pasarFoto(p, 1)"
                ><i class="fas fa-chevron-right"></i></button>
                <div class="pcard__dots">
                  <button
                    v-for="(f, i) in fotosVivas(p)"
                    :key="f.i"
                    class="pcard__dot"
                    :class="{ 'pcard__dot--active': i === posFoto(p) }"
                    :aria-label="'Foto ' + (i + 1)"
                    @click.stop="p._slide = i"
                  ></button>
                </div>
              </template>

              <span v-if="esAgotado(p)" class="badge badge--soldout">Agotado</span>
              <span v-else-if="p.descuento > 0" class="badge badge--sale">-{{ formatoPct(p.descuento) }}%</span>
            </div>

            <div class="pcard__info">
              <h3 class="pcard__title">{{ p.descrip }}</h3>
              <div v-if="p.precio > 0" class="pcard__price-row">
                <span class="pcard__price">{{ formatoCOP(precioFinal(p)) }}</span>
                <span v-if="trm > 0" class="tag tag--cop">COP</span>
                <s v-if="p.descuento > 0" class="price-old">{{ formatoCOP(p.precio) }}</s>
                <span v-if="trm > 0" class="tag tag--usd">USD {{ formatoUSD(precioFinal(p)) }}</span>
              </div>
              <p v-else class="pcard__ref">Precio a consultar</p>
              <p v-if="p.codigo" class="pcard__ref">Ref. {{ p.codigo }}</p>
            </div>
          </article>
        </div>
      </div>
    </main>

    <!-- Detalle de producto (estilo tienda): galería + color/talla + descripción -->
    <main v-if="productId" class="collection pdp">
      <div class="container-x">
        <div class="pdp__nav">
          <button class="pdp__back" @click="goBack">
            <i class="fas fa-arrow-left"></i> Volver al catálogo
          </button>
          <span v-if="detailProduct && detailProduct.categoria_nombre" class="pdp__crumb">
            <template v-if="detailProduct.categoria_padre_nombre">{{ detailProduct.categoria_padre_nombre }} / </template>{{ detailProduct.categoria_nombre }}
          </span>
        </div>

        <div v-if="loading" class="pdp__loading"><i class="fas fa-spinner fa-spin"></i></div>

        <div v-else-if="!detailProduct" class="shop-state">
          <i class="fas fa-tshirt shop-state__icon"></i>
          <p>Este producto ya no está disponible</p>
          <button class="shop-state__link" @click="goBack">Volver al catálogo</button>
        </div>

        <div v-else class="pdp__grid">
          <!-- Galería -->
          <div class="pdp__media">
            <div
              class="pgal"
              :class="{ 'pgal--zoom': galZoom }"
              @touchstart.passive="onGalTouchStart"
              @touchmove="onGalTouchMove"
              @touchend="onGalTouchEnd"
              @mousemove="onZoomMove"
              @mouseleave="onZoomLeave"
              @click="openLightbox"
            >
              <transition name="slidefade" mode="out-in">
                <img
                  v-if="galImageUrl"
                  :key="galImageUrl"
                  :src="galImageUrl"
                  :alt="detailProduct.descrip"
                  :class="{ 'img-pending': !isImgLoaded(galImageUrl) }"
                  @load="onImgLoad(galImageUrl)"
                  @error="onGalSlideError"
                />
                <i v-else class="fas fa-tshirt pcard__placeholder"></i>
              </transition>
              <span v-if="galImageUrl && !isImgLoaded(galImageUrl)" class="img-spinner"></span>
              <span v-if="pdpAgotado" class="badge badge--soldout">Agotado</span>
              <span v-else-if="detailProduct.descuento > 0" class="badge badge--sale">-{{ formatoPct(detailProduct.descuento) }}%</span>
              <button
                v-if="galImageUrl"
                class="pgal__zoom"
                :aria-label="galZoom ? 'Quitar zoom' : 'Ampliar imagen'"
                @click.stop="toggleGalZoom"
              >
                <i :class="galZoom ? 'fas fa-search-minus' : 'fas fa-search-plus'"></i>
              </button>
              <template v-if="galSlides.length > 1">
                <button class="gal-arrow gal-arrow--prev" aria-label="Foto anterior" @click.stop="galStep(-1)">
                  <i class="fas fa-chevron-left"></i>
                </button>
                <button class="gal-arrow gal-arrow--next" aria-label="Foto siguiente" @click.stop="galStep(1)">
                  <i class="fas fa-chevron-right"></i>
                </button>
                <span class="pgal__counter">{{ galPos + 1 }} / {{ galSlides.length }}</span>
              </template>
            </div>
            <div v-if="galSlides.length > 1" class="pgal__thumbs">
              <button
                v-for="(s, i) in galSlides"
                :key="s.url"
                class="pgal__thumb"
                :class="{ 'pgal__thumb--active': i === galPos }"
                :aria-label="'Foto ' + (i + 1)"
                @click="galPos = i"
              >
                <img :src="s.url" alt="" loading="lazy" />
              </button>
            </div>
          </div>

          <!-- Información y compra -->
          <div class="pdp__info">
            <p v-if="detailProduct.codigo" class="pdp__ref">Ref. {{ detailProduct.codigo }}</p>
            <h1 class="pdp__title">{{ detailProduct.descrip }}</h1>

            <div v-if="detailProduct.precio > 0" class="vprice">
              <span class="vprice__label">Precio</span>
              <div class="vprice__row">
                <span class="vprice__value">{{ formatoCOP(precioFinal(detailProduct)) }}</span>
                <span class="vprice__cur">COP</span>
                <s v-if="detailProduct.descuento > 0" class="vprice__old">{{ formatoCOP(detailProduct.precio) }}</s>
                <span v-if="detailProduct.descuento > 0" class="tag tag--sale">
                  -{{ formatoPct(detailProduct.descuento) }}%
                </span>
              </div>
              <span v-if="trm > 0" class="tag tag--usd vprice__usd">
                USD {{ formatoUSD(precioFinal(detailProduct)) }}
              </span>
            </div>
            <p v-else class="pcard__ref">Precio a consultar</p>

            <div v-if="pdpCargandoVariantes" class="pdp__loading pdp__loading--sm">
              <i class="fas fa-spinner fa-spin"></i>
            </div>

            <template v-else>
              <!-- Color -->
              <div v-if="pdpColors.length" class="pdp__opt">
                <div class="pdp__opt-label">
                  Color: <strong>{{ pdpSelectedColor ? pdpSelectedColor.name : 'Selecciona un color' }}</strong>
                </div>
                <div class="pdp__swatches">
                  <button
                    v-for="c in pdpColors"
                    :key="c.key"
                    class="pdp__swatch"
                    :class="{
                      'pdp__swatch--active': pdpColorKey === c.key,
                      'pdp__swatch--out': c.soldOut,
                      'pdp__swatch--text': !c.hex,
                    }"
                    :title="c.name + (c.soldOut ? ' (agotado)' : '')"
                    @click="selectColor(c.key)"
                  >
                    <span v-if="c.hex" class="pdp__swatch-dot" :style="{ background: c.hex }"></span>
                    <span class="pdp__swatch-name">{{ c.name }}</span>
                  </button>
                </div>
              </div>

              <!-- Talla (las del color elegido) -->
              <div v-if="pdpHasSizes" class="pdp__opt">
                <div class="pdp__opt-label">
                  Talla: <strong>{{ pdpVariant ? pdpVariant.destalla : 'Selecciona una talla' }}</strong>
                </div>
                <p v-if="pdpColors.length && !pdpColorKey" class="pdp__hint">Primero elige un color.</p>
                <div v-else class="pdp__sizes">
                  <button
                    v-for="v in pdpSizes"
                    :key="v.serialid"
                    class="pdp__size"
                    :class="{
                      'pdp__size--active': pdpVariant && pdpVariant.serialid === v.serialid,
                      'pdp__size--out': varianteAgotada(v),
                    }"
                    :disabled="varianteAgotada(v)"
                    :title="varianteAgotada(v) ? 'Agotada' : 'Disponibles: ' + v.saldo"
                    @click="selectSize(v)"
                  >{{ v.destalla }}</button>
                </div>
              </div>

              <!-- Cantidad + agregar -->
              <div class="pdp__buy">
                <p v-if="pdpRow" class="pdp__stock">
                  <template v-if="pdpMax > 0">Disponibles: {{ stockLabel(pdpMax) }}</template>
                  <template v-else>Ya agregaste todas las unidades disponibles</template>
                  <span v-if="pdpInCart > 0" class="pdp__incart"> · {{ pdpInCart }} en tu carrito</span>
                </p>
                <div class="pdp__buy-row">
                  <span class="stepper stepper--lg">
                    <button aria-label="Restar" :disabled="pdpQty <= 1" @click="pdpQty--">
                      <i class="fas fa-minus"></i>
                    </button>
                    <input
                      class="stepper__input"
                      type="text"
                      inputmode="numeric"
                      :value="pdpQty"
                      @input="pdpQtyInput"
                    />
                    <button aria-label="Sumar" :disabled="!pdpRow || pdpQty >= pdpMax" @click="pdpQty++">
                      <i class="fas fa-plus"></i>
                    </button>
                  </span>
                  <button
                    class="btn btn--dark pdp__add"
                    :disabled="!pdpRow || pdpMax <= 0"
                    @click="addFromDetail"
                  >
                    <i class="fas fa-cart-plus"></i> {{ pdpAddLabel }}
                  </button>
                </div>
                <p class="pdp__hint">
                  Mínimo {{ MINIMO }} unidades por pedido (puedes combinar productos, tallas y colores).
                </p>
              </div>
            </template>

            <!-- Descripción -->
            <div v-if="detailProduct.descripcion" class="pdp__section">
              <h2 class="pdp__section-title">Descripción</h2>
              <p class="pdp__desc">{{ detailProduct.descripcion }}</p>
            </div>
          </div>
        </div>

        <!-- Productos relacionados (misma categoría) -->
        <section v-if="detailProduct && relatedProducts.length" class="rel">
          <div class="rel__head">
            <h2 class="rel__title">Productos relacionados</h2>
            <div class="rel__nav">
              <button class="rel__arrow" aria-label="Anteriores" :disabled="!relCanLeft" @click="scrollRelated(-1)">
                <i class="fas fa-chevron-left"></i>
              </button>
              <button class="rel__arrow" aria-label="Siguientes" :disabled="!relCanRight" @click="scrollRelated(1)">
                <i class="fas fa-chevron-right"></i>
              </button>
            </div>
          </div>
          <div ref="relTrack" class="rel__track" @scroll.passive="updateRelArrows">
            <article v-for="p in relatedProducts" :key="p.matid" class="rel__item pcard" @click="openRelated(p)">
              <div class="pcard__media">
                <img
                  v-if="fotoActual(p)"
                  :src="fotoActual(p)"
                  :alt="p.descrip"
                  :class="{ 'img-pending': !isImgLoaded(fotoActual(p)) }"
                  loading="lazy"
                  @load="onImgLoad(fotoActual(p))"
                  @error="onFotoError(p)"
                />
                <i v-else class="fas fa-tshirt pcard__placeholder"></i>
                <span v-if="fotoActual(p) && !isImgLoaded(fotoActual(p))" class="img-spinner"></span>
                <span v-if="esAgotado(p)" class="badge badge--soldout">Agotado</span>
                <span v-else-if="p.descuento > 0" class="badge badge--sale">-{{ formatoPct(p.descuento) }}%</span>
              </div>
              <div class="pcard__info">
                <h3 class="pcard__title">{{ p.descrip }}</h3>
                <div v-if="p.precio > 0" class="pcard__price-row">
                  <span class="pcard__price">{{ formatoCOP(precioFinal(p)) }}</span>
                  <s v-if="p.descuento > 0" class="price-old">{{ formatoCOP(p.precio) }}</s>
                </div>
                <p v-else class="pcard__ref">Precio a consultar</p>
              </div>
            </article>
          </div>
        </section>
      </div>
    </main>

    <!-- 8) Footer -->
    <footer class="shop-footer">
      <img v-if="logoSrc && !logoFailed" :src="logoSrc" alt="Logo" class="shop-footer__logo" @error="logoFailed = true" />
      <img v-else :src="logoFallback" alt="Logo" class="shop-footer__logo" />
      <p class="shop-footer__name">{{ nombreTienda }}</p>
      <p class="shop-footer__tagline">Catálogo mayorista · Mínimo 6 unidades por pedido</p>
      <p class="shop-footer__copy">© {{ anio }} {{ nombreTienda }}. Todos los derechos reservados.</p>
    </footer>

    <!-- Menú de categorías: cubre todo el catálogo -->
    <transition name="ofade">
      <div v-if="catMenuOpen" class="catmenu">
        <div class="catmenu__head">
          <span class="catmenu__title">Categorías</span>
          <button class="icon-btn" aria-label="Cerrar" @click="catMenuOpen = false">
            <i class="fas fa-times"></i>
          </button>
        </div>
        <div class="catmenu__body">
          <button
            class="catmenu__item"
            :class="{ 'catmenu__item--active': activeCat === null }"
            @click="seleccionarCategoria(null)"
          >
            <span>Todo el catálogo</span>
            <span class="catmenu__count">{{ productos.length }}</span>
          </button>
          <div v-for="g in categoriaGrupos" :key="g.nombre || '_'" class="catmenu__group">
            <div v-if="g.nombre" class="catmenu__group-title">{{ g.nombre }}</div>
            <button
              v-for="cat in g.items"
              :key="cat.id"
              class="catmenu__item"
              :class="{ 'catmenu__item--active': activeCat === cat.id }"
              @click="seleccionarCategoria(cat.id)"
            >
              <span>{{ cat.nombre }}</span>
              <span class="catmenu__count">{{ conteoCategoria(cat) }}</span>
            </button>
          </div>
        </div>
      </div>
    </transition>

    <!-- 9) Drawer del carrito -->
    <transition name="ofade">
      <div v-if="cartOpen" class="cart-overlay" @click="closeCart"></div>
    </transition>
    <aside class="cart" :class="{ 'cart--open': cartOpen }" aria-label="Carrito">
      <div class="cart__head">
        <h2 class="cart__title">Tu carrito ({{ cartCount }})</h2>
        <button class="icon-btn" aria-label="Cerrar carrito" @click="closeCart">
          <i class="fas fa-times"></i>
        </button>
      </div>

      <div v-if="cart.length === 0" class="cart__empty">
        <i class="fas fa-shopping-bag cart__empty-icon"></i>
        <p>Tu carrito está vacío</p>
        <button class="btn btn--dark btn--block" @click="closeCart">Continuar comprando</button>
      </div>

      <div v-else class="cart__items">
        <div v-for="item in cart" :key="item.key" class="cart__item">
          <div class="cart__thumb">
            <img v-if="item.imagen" :src="item.imagen" :alt="item.nombre" />
            <i v-else class="fas fa-tshirt"></i>
          </div>
          <div class="cart__item-info">
            <p class="cart__item-name">{{ item.nombre }}</p>
            <span v-if="item.detalle" class="cart__item-variant">{{ item.detalle }}</span>
            <p class="cart__item-price">{{ formatoCOP(item.precio) }} c/u</p>
            <div class="cart__item-row">
              <span class="stepper">
                <button aria-label="Restar" @click="cambiarCantidad(item, -1)">
                  <i class="fas fa-minus"></i>
                </button>
                <input
                  class="stepper__input"
                  type="text"
                  inputmode="numeric"
                  :value="item.qty"
                  @input="lineInput(item, $event)"
                />
                <button
                  aria-label="Sumar"
                  :disabled="item.maxQty > 0 && item.qty >= item.maxQty"
                  @click="cambiarCantidad(item, 1)"
                >
                  <i class="fas fa-plus"></i>
                </button>
              </span>
              <button class="cart__item-remove" @click="eliminarLinea(item)">Eliminar</button>
            </div>
          </div>
          <span class="cart__item-total">{{ formatoCOP(item.precio * item.qty) }}</span>
        </div>
      </div>

      <div v-if="cart.length > 0" class="cart__foot">
        <div class="cart__minbar">
          <div class="cart__minbar-rail">
            <div class="cart__minbar-fill" :style="{ width: minProgress * 100 + '%' }"></div>
          </div>
          <p class="cart__minbar-text" :class="{ 'cart__minbar-text--ok': cartCount >= MINIMO }">
            {{ cartCount }}/{{ MINIMO }} unidades · mínimo por pedido
          </p>
        </div>

        <div class="cart__subtotal">
          <span class="cart__subtotal-label">Subtotal</span>
          <span class="cart__subtotal-value">
            {{ formatoCOP(cartTotal) }}
            <span v-if="trm > 0" class="tag tag--cop">COP</span>
            <span v-if="trm > 0" class="tag tag--usd">USD {{ formatoUSD(cartTotal) }}</span>
          </span>
        </div>
        <div class="cart__shipping">
          <span class="cart__subtotal-label">Envío</span>
          <span class="cart__shipping-value">Se cotiza al despachar</span>
        </div>

        <p class="cart__note">
          <i class="fas fa-truck"></i> El valor del envío se cotiza al momento del despacho.
        </p>
        <p class="cart__note">
          <i class="fab fa-whatsapp"></i> El pedido se envía y confirma por WhatsApp.
        </p>

        <form class="cart__form" @submit.prevent="enviarPedido">
          <input
            v-model="form.nombre"
            type="text"
            class="field"
            placeholder="Nombre completo *"
          />
          <div class="cart__form-row">
            <select v-model="form.departamento" class="field">
              <option value="" disabled>Departamento *</option>
              <option v-for="d in dptos" :key="d" :value="d">{{ d }}</option>
            </select>
            <select v-model="form.ciudad" class="field" :disabled="!form.departamento">
              <option value="" disabled>Ciudad *</option>
              <option v-for="c in ciudadesFiltradas" :key="c" :value="c">{{ c }}</option>
            </select>
          </div>
          <input
            v-model="form.direccion"
            type="text"
            class="field"
            placeholder="Dirección *"
          />

          <button
            type="submit"
            class="btn btn--dark btn--block"
            :disabled="!formCompleta || sending"
          >
            <i v-if="sending" class="fas fa-spinner fa-spin"></i>
            <template v-else><i class="fab fa-whatsapp"></i> Enviar pedido por WhatsApp</template>
          </button>
          <p v-if="orderError" class="cart__error">{{ orderError }}</p>
        </form>
      </div>
    </aside>

    <!-- 10) Visor de fotos a pantalla completa: clic para ampliar y mover el mouse/dedo para recorrer -->
    <transition name="ofade">
      <div
        v-if="lbOpen && lbSlides.length"
        class="lb"
        role="dialog"
        aria-modal="true"
        @click.self="closeLightbox"
      >
        <div
          ref="lbStage"
          class="lb__stage"
          :class="{ 'lb__stage--zoom': lbZoom }"
          @click="toggleLbZoom"
          @mousemove="onLbMove"
          @touchstart.passive="onLbTouchStart"
          @touchmove="onLbTouchMove"
          @touchend="onLbTouchEnd"
        >
          <transition name="slidefade" mode="out-in">
            <img
              :key="lbSlides[lbPos]"
              :src="lbSlides[lbPos]"
              :alt="detailProduct ? detailProduct.descrip : ''"
              :class="{ 'img-pending': !isImgLoaded(lbSlides[lbPos]) }"
              draggable="false"
              @load="onImgLoad(lbSlides[lbPos])"
            />
          </transition>
          <span v-if="!isImgLoaded(lbSlides[lbPos])" class="img-spinner"></span>
        </div>
        <span v-if="lbSlides.length > 1" class="lb__counter">{{ lbPos + 1 }} / {{ lbSlides.length }}</span>
        <div class="lb__controls">
          <button v-if="lbSlides.length > 1" class="lb__btn" aria-label="Foto anterior" @click="lbStep(-1)">
            <i class="fas fa-chevron-left"></i>
          </button>
          <button class="lb__btn lb__btn--close" aria-label="Cerrar" @click="closeLightbox">
            <i class="fas fa-times"></i>
          </button>
          <button v-if="lbSlides.length > 1" class="lb__btn" aria-label="Foto siguiente" @click="lbStep(1)">
            <i class="fas fa-chevron-right"></i>
          </button>
        </div>
      </div>
    </transition>

    <!-- 11) Botón flotante del carrito: aparece cuando hay productos -->
    <transition name="fab">
      <button
        v-if="cart.length > 0 && !cartOpen && !lbOpen"
        class="cart-fab"
        :class="{ 'cart-fab--bump': fabBump }"
        aria-label="Ver carrito"
        @click="openCart"
      >
        <i class="fas fa-shopping-cart"></i>
        <span class="cart-fab__badge">{{ cartBubble }}</span>
      </button>
    </transition>
  </div>
</template>

<script>
import catalogService from '@/services/catalog.service';
import logoFallback from '@/assets/img/logo-sm.png';

// Mínimo de unidades totales por pedido
const MIN_TOTAL_UNIDADES = 6;

export default {
  name: 'PublicCatalog',
  data() {
    return {
      MINIMO: MIN_TOTAL_UNIDADES,
      anio: new Date().getFullYear(),
      nombreTienda: '',
      token: '',
      logoFallback,
      logoSrc: '',
      logoFailed: false,
      vendedorNombre: '',
      trm: 0,
      // Banners de promoción: [{ desktop, mobile }] con rutas relativas al storage
      banners: [],
      bannerPos: 0,
      bannerTimer: null,
      bannerTouchX: null,
      productos: [],
      loading: true,
      error: false,
      search: '',
      sortBy: 'destacados',
      activeCat: null,
      catMenuOpen: false,
      chipsCanLeft: false,
      chipsCanRight: false,
      scrolled: false,
      // Carrito (agrupa por matid + serialid)
      cart: [],
      cartOpen: false,
      fabBump: false,
      // Variantes (seriales) por matid: { loading, list }
      variantesCache: {},
      // Detalle de producto: color (clave) y variante elegidos, cantidad y galería
      pdpColorKey: null,
      pdpVariantId: null,
      pdpQty: 1,
      galPos: 0,
      galZoom: false,
      galDead: [],
      galTouchX: null,
      // URLs de imágenes ya cargadas (mientras tanto se muestra un spinner)
      loadedImgs: {},
      // Visor a pantalla completa
      lbOpen: false,
      lbPos: 0,
      lbZoom: false,
      lbTouch: null,
      // Carrusel de relacionados
      relCanLeft: false,
      relCanRight: false,
      // Posición del scroll del catálogo para restaurarla al volver del detalle
      catalogScrollY: 0,
      cameFromCatalog: false,
      // Checkout
      form: { nombre: '', departamento: '', ciudad: '', direccion: '' },
      ciudadesData: [],
      sending: false,
      orderError: '',
    };
  },
  computed: {
    cartCount() {
      return this.cart.reduce((s, i) => s + i.qty, 0);
    },
    cartTotal() {
      return this.cart.reduce((s, i) => s + i.precio * i.qty, 0);
    },
    cartBubble() {
      return this.cartCount > 99 ? '99+' : String(this.cartCount);
    },
    minProgress() {
      return Math.min(this.cartCount / MIN_TOTAL_UNIDADES, 1);
    },
    formCompleta() {
      const f = this.form;
      return !!(f.nombre && f.departamento && f.ciudad && f.direccion) && !this.sending;
    },
    dptos() {
      return [...new Set(this.ciudadesData.map((c) => c.DPTO))].sort((a, b) =>
        a.localeCompare(b, 'es')
      );
    },
    ciudadesFiltradas() {
      return this.ciudadesData
        .filter((c) => c.DPTO === this.form.departamento)
        .map((c) => c.NOMBRE)
        .sort((a, b) => a.localeCompare(b, 'es'));
    },
    categorias() {
      // Chips jerárquicos: el padre agrupa sus subcategorías
      const mapa = new Map();
      for (const p of this.productos) {
        if (p.categoria_id != null && p.categoria_padre_id != null) {
          if (!mapa.has(p.categoria_padre_id)) {
            mapa.set(p.categoria_padre_id, {
              id: p.categoria_padre_id,
              label: p.categoria_padre_nombre,
              nombre: p.categoria_padre_nombre,
              padre: null,
              esPadre: true,
            });
          } else {
            // Pudo registrarse antes por un producto directo del padre
            mapa.get(p.categoria_padre_id).esPadre = true;
          }
          if (!mapa.has(p.categoria_id)) {
            mapa.set(p.categoria_id, {
              id: p.categoria_id,
              label: `${p.categoria_padre_nombre} > ${p.categoria_nombre}`,
              nombre: p.categoria_nombre,
              padre: p.categoria_padre_nombre,
              esPadre: false,
            });
          }
        } else if (p.categoria_id != null && !mapa.has(p.categoria_id)) {
          mapa.set(p.categoria_id, {
            id: p.categoria_id,
            label: p.categoria_nombre,
            nombre: p.categoria_nombre,
            padre: null,
            esPadre: false,
          });
        }
      }
      return [...mapa.values()];
    },
    // Categorías agrupadas por su padre para el menú (las sin padre van primero)
    categoriaGrupos() {
      const grupos = new Map([[null, []]]);
      this.categorias.forEach((c) => {
        if (!grupos.has(c.padre)) grupos.set(c.padre, []);
        grupos.get(c.padre).push(c);
      });
      return [...grupos.entries()]
        .filter(([, items]) => items.length)
        .map(([nombre, items]) => ({ nombre, items }));
    },
    productosFiltrados() {
      const q = this.search.trim().toLowerCase();
      let lista = this.productos.filter((p) => {
        if (q) {
          const campos = `${p.descrip} ${p.codigo} ${p.marca_descrip}`.toLowerCase();
          if (!campos.includes(q)) return false;
        }
        if (this.activeCat != null) {
          const cat = this.categorias.find((c) => c.id === this.activeCat);
          if (!cat) return false;
          if (cat.esPadre) {
            if (p.categoria_id !== this.activeCat && p.categoria_padre_id !== this.activeCat) return false;
          } else if (p.categoria_id !== this.activeCat) {
            return false;
          }
        }
        return true;
      });

      const por = this.sortBy;
      if (por === 'az') lista = [...lista].sort((a, b) => a.descrip.localeCompare(b.descrip, 'es'));
      else if (por === 'za') lista = [...lista].sort((a, b) => b.descrip.localeCompare(a.descrip, 'es'));
      else if (por === 'precio_asc') lista = [...lista].sort((a, b) => this.precioFinal(a) - this.precioFinal(b));
      else if (por === 'precio_desc') lista = [...lista].sort((a, b) => this.precioFinal(b) - this.precioFinal(a));
      else if (por === 'stock') lista = [...lista].sort((a, b) => b.existencia - a.existencia);
      return lista;
    },
    // ===== Detalle de producto =====
    productId() {
      return this.$route.params.productId || null;
    },
    detailProduct() {
      if (!this.productId) return null;
      return this.productos.find((p) => String(p.matid) === String(this.productId)) || null;
    },
    pdpCargandoVariantes() {
      const p = this.detailProduct;
      if (!p || !(p.variantes_count > 0)) return false;
      const c = this.variantesCache[p.matid];
      return !c || c.loading;
    },
    // Variantes del producto ordenadas por talla
    pdpAllVariants() {
      const p = this.detailProduct;
      const c = p ? this.variantesCache[p.matid] : null;
      if (!c || c.loading) return [];
      return [...c.list].sort(this.compareSizes);
    },
    pdpAgotado() {
      const p = this.detailProduct;
      if (!p) return false;
      if (this.esAgotado(p)) return true;
      return this.pdpAllVariants.length > 0 && this.pdpAllVariants.every(this.varianteAgotada);
    },
    pdpHasColors() {
      return this.pdpAllVariants.some((v) => (v.descolor || '').trim());
    },
    pdpHasSizes() {
      return this.pdpAllVariants.some((v) => (v.destalla || '').trim());
    },
    // Colores únicos en el orden en que aparecen; agotado si ninguna talla tiene stock
    pdpColors() {
      if (!this.pdpHasColors) return [];
      const map = new Map();
      this.pdpAllVariants.forEach((v) => {
        const key = this.colorKey(v);
        const c = map.get(key) || { key, name: (v.descolor || '').trim() || 'Sin color', hex: v.colormin, soldOut: true };
        if (!c.hex && v.colormin) c.hex = v.colormin;
        if (!this.varianteAgotada(v)) c.soldOut = false;
        map.set(key, c);
      });
      return [...map.values()];
    },
    pdpSelectedColor() {
      return this.pdpColors.find((c) => c.key === this.pdpColorKey) || null;
    },
    // Tallas del color elegido (o todas si el producto no maneja color)
    pdpSizes() {
      if (!this.pdpHasColors) return this.pdpAllVariants;
      if (this.pdpColorKey === null) return [];
      return this.pdpAllVariants.filter((v) => this.colorKey(v) === this.pdpColorKey);
    },
    pdpVariant() {
      return this.pdpSizes.find((v) => v.serialid === this.pdpVariantId) || null;
    },
    // Lo que se agrega al carrito: la variante elegida o, sin variantes, el producto
    pdpRow() {
      const p = this.detailProduct;
      if (!p || this.pdpCargandoVariantes) return null;
      if (this.pdpAllVariants.length) return this.pdpVariant;
      return { serialid: '_single', single: true, saldo: parseInt(p.existencia, 10) || 0 };
    },
    pdpInCart() {
      if (!this.detailProduct || !this.pdpRow) return 0;
      const line = this.cart.find((l) => l.key === this.lineKey(this.detailProduct, this.pdpRow));
      return line ? line.qty : 0;
    },
    // Unidades que aún se pueden agregar (stock menos lo que ya está en el carrito)
    pdpMax() {
      const row = this.pdpRow;
      if (!row) return 0;
      return Math.max(0, (parseInt(row.saldo, 10) || 0) - this.pdpInCart);
    },
    pdpAddLabel() {
      if (!this.detailProduct) return '';
      if (this.pdpAgotado) return 'Agotado';
      if (!this.pdpRow) {
        return this.pdpHasColors && this.pdpColorKey === null ? 'Selecciona un color' : 'Selecciona una talla';
      }
      return 'Agregar al carrito';
    },
    // Galería: foto principal + fotos adicionales que cargan bien
    galSlides() {
      const p = this.detailProduct;
      if (!p) return [];
      return [...new Set(p._fotos || [])]
        .filter((url) => !this.galDead.includes(url))
        .map((url) => ({ url }));
    },
    galImageUrl() {
      return this.galSlides[this.galPos]?.url || null;
    },
    lbSlides() {
      return this.galSlides.map((s) => s.url);
    },
    // Productos de la misma categoría (si no hay, de la categoría padre); primero los que tienen stock
    relatedProducts() {
      const p = this.detailProduct;
      if (!p) return [];
      const otros = this.productos.filter((x) => x.matid !== p.matid);
      let lista = p.categoria_id != null ? otros.filter((x) => x.categoria_id === p.categoria_id) : [];
      if (!lista.length && p.categoria_padre_id != null) {
        lista = otros.filter((x) => x.categoria_padre_id === p.categoria_padre_id || x.categoria_id === p.categoria_padre_id);
      }
      return lista
        .map((x, i) => ({ x, i }))
        .sort((a, b) => (this.esAgotado(a.x) - this.esAgotado(b.x)) || a.i - b.i)
        .slice(0, 16)
        .map((o) => o.x);
    },
  },
  watch: {
    // La ciudad se deshabilita hasta elegir departamento
    'form.departamento'() {
      this.form.ciudad = '';
    },
    cartOpen() {
      this.bloquearScroll();
    },
    catMenuOpen() {
      this.bloquearScroll();
    },
    lbOpen() {
      this.bloquearScroll();
    },
    lbPos() {
      this.lbZoom = false;
    },
    // Al cambiar de foto se quita el zoom
    galPos() {
      this.galZoom = false;
    },
    categorias() {
      this.$nextTick(this.updateChipsArrows);
    },
    relatedProducts() {
      this.$nextTick(this.updateRelArrows);
    },
    // Entrar/salir del detalle (también con el botón atrás del navegador)
    productId(id, prev) {
      this.lbOpen = false;
      if (id) {
        window.scrollTo(0, 0);
      } else if (prev) {
        this.$nextTick(() => window.scrollTo(0, this.catalogScrollY));
      }
    },
    // Producto nuevo en el detalle (o llegó después con un enlace directo)
    detailProduct(p, prev) {
      if (p && (!prev || p.matid !== prev.matid)) {
        this.resetDetail();
        this.cargarVariantes(p);
      }
    },
    // Buscar desde el detalle lleva de vuelta a la grilla
    search(q) {
      if (q && this.productId) this.goBack();
    },
  },
  mounted() {
    this.token = this.$route.params.token;
    document.title = 'Catálogo Mayorista';
    window.addEventListener('scroll', this.onScroll, { passive: true });
    window.addEventListener('resize', this.updateChipsArrows, { passive: true });
    window.addEventListener('resize', this.updateRelArrows, { passive: true });
    window.addEventListener('keydown', this.onKeydown);
    this.cargarCatalogo();
    this.cargarAjustes();
    this.cargarCiudades();
  },
  beforeUnmount() {
    window.removeEventListener('scroll', this.onScroll);
    window.removeEventListener('resize', this.updateChipsArrows);
    window.removeEventListener('resize', this.updateRelArrows);
    window.removeEventListener('keydown', this.onKeydown);
    this.stopBannerTimer();
    document.body.style.overflow = '';
  },
  methods: {
    onScroll() {
      this.scrolled = window.scrollY > 1;
    },
    onKeydown(e) {
      if (this.lbOpen) {
        if (e.key === 'Escape') this.closeLightbox();
        else if (e.key === 'ArrowLeft') this.lbStep(-1);
        else if (e.key === 'ArrowRight') this.lbStep(1);
        return;
      }
      if (e.key === 'Escape') {
        if (this.cartOpen) this.closeCart();
        else if (this.catMenuOpen) this.catMenuOpen = false;
      }
    },
    bloquearScroll() {
      const bloqueado = this.cartOpen || this.catMenuOpen || this.lbOpen;
      document.body.style.overflow = bloqueado ? 'hidden' : '';
    },
    async cargarCatalogo() {
      this.loading = true;
      this.error = false;
      try {
        const res = await catalogService.getCatalogo(this.token);
        this.vendedorNombre = res.data.vendedor?.nombre || '';
        // Foto principal (imagen) + fotos adicionales del inventario, en ese orden
        this.productos = (res.data.productos || []).map((p) => ({
          ...p,
          precio: parseFloat(p.precio) || 0,
          descuento: Math.min(100, Math.max(0, parseFloat(p.descuento) || 0)),
          _fotos: [p.imagen, ...(p.fotos || [])].filter(Boolean).map(this.resolveImagen),
          _slide: 0,
          _dead: [],
        }));
      } catch (e) {
        console.error('Error cargando catálogo:', e);
        this.error = true;
      } finally {
        this.loading = false;
      }
    },
    async cargarAjustes() {
      try {
        const res = await catalogService.getPublicSettings();
        const s = res.data || {};
        this.trm = parseFloat(s.trm_dolar) || 0;
        // La marca se toma de la configuración; "MiStock" solo si no hay nada definido
        this.nombreTienda = String(s.company_name || '').trim() || 'MiStock';
        document.title = `Catálogo Mayorista — ${this.nombreTienda}`;
        const ruta = s.logo_url || s.logo_path || '';
        this.logoSrc = this.resolveImagen(ruta);
        this.banners = s.banners || [];
        this.startBannerTimer();
      } catch (e) {
        console.error('Error cargando ajustes públicos:', e);
      }
    },
    async cargarCiudades() {
      try {
        const res = await fetch(`${process.env.BASE_URL}ciudades.json?v=${Date.now()}`);
        this.ciudadesData = await res.json();
      } catch (e) {
        console.error('Error cargando ciudades:', e);
      }
    },
    // Variantes (talla/color) del producto; se piden una sola vez por producto
    async cargarVariantes(p) {
      const id = p.matid;
      if (this.variantesCache[id]) return;
      if (!(p.variantes_count > 0)) {
        this.variantesCache = { ...this.variantesCache, [id]: { loading: false, list: [] } };
        return;
      }
      this.variantesCache = { ...this.variantesCache, [id]: { loading: true, list: [] } };
      let list = [];
      try {
        const res = await catalogService.getSerials(this.token, id);
        list = res.data || [];
      } catch (e) {
        console.error('Error cargando variantes:', e);
      }
      this.variantesCache = { ...this.variantesCache, [id]: { loading: false, list } };
      if (this.detailProduct && this.detailProduct.matid === id) this.initSeleccion();
    },
    // Las imágenes se resuelven contra VUE_APP_API_IMAGE_URL + /storage/{path}
    resolveImagen(ruta) {
      if (!ruta) return '';
      if (ruta.startsWith('http')) return ruta;
      const base = (process.env.VUE_APP_API_IMAGE_URL || '').trim().replace(/\/?$/, '/');
      return base + String(ruta).replace(/^\/?storage\//, '').replace(/^\/+/, '');
    },
    stockLabel(n) {
      return n >= 1000 ? '999+' : String(n);
    },
    esAgotado(p) {
      return (parseFloat(p.existencia) || 0) <= 0;
    },
    varianteAgotada(v) {
      return (parseInt(v.saldo, 10) || 0) <= 0;
    },
    formatoCOP(v) {
      return '$' + Math.round(parseFloat(v) || 0).toLocaleString('es-CO');
    },
    formatoUSD(v) {
      return '$' + ((parseFloat(v) || 0) / this.trm).toFixed(2);
    },
    formatoPct(n) {
      return String(Math.round(n * 100) / 100).replace('.', ',');
    },
    // Precio con el descuento del producto (o el general de la tienda) ya aplicado
    precioFinal(p) {
      const d = p.descuento || 0;
      return d > 0 ? Math.round(p.precio * (1 - d / 100)) : p.precio;
    },
    limpiarFiltros() {
      this.search = '';
      this.activeCat = null;
    },
    conteoCategoria(cat) {
      return this.productos.filter((p) =>
        cat.esPadre
          ? p.categoria_id === cat.id || p.categoria_padre_id === cat.id
          : p.categoria_id === cat.id
      ).length;
    },
    // Elige la categoría desde el menú y sube hasta la toolbar si se está más abajo
    async seleccionarCategoria(id) {
      this.activeCat = id;
      this.catMenuOpen = false;
      // Desde el detalle se vuelve primero a la grilla
      if (this.productId) {
        this.goBack();
        await new Promise((resolve) => {
          const stop = this.$watch('productId', () => {
            stop();
            setTimeout(resolve, 0);
          });
        });
      }
      this.$nextTick(() => {
        const el = this.$refs.toolbar;
        if (!el) return;
        const headerH = this.$el.querySelector('.header')?.offsetHeight || 0;
        const top = el.getBoundingClientRect().top + window.scrollY - headerH - 8;
        if (window.scrollY > top) window.scrollTo({ top, behavior: 'smooth' });
      });
    },
    // ===== Carga de imágenes =====
    onImgLoad(url) {
      if (url && !this.loadedImgs[url]) this.loadedImgs[url] = true;
    },
    isImgLoaded(url) {
      return !!this.loadedImgs[url];
    },
    // ===== Zoom al pasar el mouse: la imagen se amplía siguiendo el cursor =====
    onZoomMove(e) {
      const el = e.currentTarget;
      const r = el.getBoundingClientRect();
      el.style.setProperty('--zx', `${((e.clientX - r.left) / r.width) * 100}%`);
      el.style.setProperty('--zy', `${((e.clientY - r.top) / r.height) * 100}%`);
    },
    onZoomLeave(e) {
      e.currentTarget.style.setProperty('--zx', '50%');
      e.currentTarget.style.setProperty('--zy', '50%');
    },
    // ===== Banners =====
    bannerStep(dir) {
      const n = this.banners.length;
      if (n < 2) return;
      this.bannerPos = (this.bannerPos + dir + n) % n;
      this.startBannerTimer();
    },
    goBanner(i) {
      this.bannerPos = i;
      this.startBannerTimer();
    },
    startBannerTimer() {
      this.stopBannerTimer();
      if (this.banners.length < 2) return;
      this.bannerTimer = setInterval(() => {
        this.bannerPos = (this.bannerPos + 1) % this.banners.length;
      }, 5000);
    },
    stopBannerTimer() {
      if (this.bannerTimer) clearInterval(this.bannerTimer);
      this.bannerTimer = null;
    },
    onBannerTouchStart(e) {
      this.bannerTouchX = e.changedTouches[0].clientX;
    },
    onBannerTouchEnd(e) {
      if (this.bannerTouchX === null) return;
      const dx = e.changedTouches[0].clientX - this.bannerTouchX;
      this.bannerTouchX = null;
      if (Math.abs(dx) > 40) this.bannerStep(dx < 0 ? 1 : -1);
    },
    // ===== Chips de categorías =====
    // Rueda vertical del mouse -> scroll horizontal de los chips
    onChipsWheel(e) {
      const el = e.currentTarget;
      if (el.scrollWidth <= el.clientWidth || Math.abs(e.deltaX) >= Math.abs(e.deltaY)) return;
      el.scrollLeft += e.deltaY;
      e.preventDefault();
    },
    // Muestra las flechas solo hacia el lado donde quedan categorías por ver
    updateChipsArrows() {
      const el = this.$refs.chips;
      if (!el) return;
      this.chipsCanLeft = el.scrollLeft > 2;
      this.chipsCanRight = el.scrollLeft + el.clientWidth < el.scrollWidth - 2;
    },
    scrollChips(dir) {
      const el = this.$refs.chips;
      if (el) el.scrollBy({ left: dir * el.clientWidth * 0.7, behavior: 'smooth' });
    },
    // ===== Carrusel de fotos de la tarjeta =====
    // Fotos que cargan bien (las que fallan se descartan del carrusel)
    fotosVivas(p) {
      return (p._fotos || [])
        .map((url, i) => ({ url, i }))
        .filter((f) => !p._dead.includes(f.i));
    },
    posFoto(p) {
      return Math.max(0, Math.min(p._slide || 0, this.fotosVivas(p).length - 1));
    },
    fotoActual(p) {
      const vivas = this.fotosVivas(p);
      return vivas.length ? vivas[this.posFoto(p)].url : null;
    },
    pasarFoto(p, dir) {
      const n = this.fotosVivas(p).length;
      if (n < 2) return;
      p._slide = (this.posFoto(p) + dir + n) % n;
    },
    onFotoError(p) {
      const vivas = this.fotosVivas(p);
      if (!vivas.length) return;
      p._dead = [...p._dead, vivas[this.posFoto(p)].i];
      p._slide = this.posFoto(p);
    },
    // ===== Galería del detalle =====
    galStep(dir) {
      const n = this.galSlides.length;
      if (n < 2) return;
      this.galPos = (this.galPos + dir + n) % n;
    },
    onGalSlideError() {
      const s = this.galSlides[this.galPos];
      if (!s) return;
      this.galDead = [...this.galDead, s.url];
      this.galPos = Math.min(this.galPos, Math.max(0, this.galSlides.length - 1));
    },
    // Zoom con la lupa (pensado para táctil, donde no hay hover)
    toggleGalZoom(e) {
      this.galZoom = !this.galZoom;
      const el = e.currentTarget.closest('.pgal');
      el.style.setProperty('--zx', '50%');
      el.style.setProperty('--zy', '50%');
    },
    onGalTouchStart(e) {
      this.galTouchX = e.changedTouches[0].clientX;
    },
    // Con zoom activo, arrastrar el dedo recorre la imagen en vez de cambiar de foto
    onGalTouchMove(e) {
      if (!this.galZoom) return;
      e.preventDefault();
      const t = e.touches[0];
      const el = e.currentTarget;
      const r = el.getBoundingClientRect();
      const clamp = (v) => Math.min(100, Math.max(0, v));
      el.style.setProperty('--zx', `${clamp(((t.clientX - r.left) / r.width) * 100)}%`);
      el.style.setProperty('--zy', `${clamp(((t.clientY - r.top) / r.height) * 100)}%`);
    },
    onGalTouchEnd(e) {
      if (this.galZoom) {
        this.galTouchX = null;
        return;
      }
      if (this.galTouchX === null) return;
      const dx = e.changedTouches[0].clientX - this.galTouchX;
      this.galTouchX = null;
      if (Math.abs(dx) > 40) this.galStep(dx < 0 ? 1 : -1);
    },
    // ===== Visor a pantalla completa =====
    openLightbox() {
      if (!this.galImageUrl) return;
      this.galZoom = false;
      this.lbPos = Math.max(0, this.lbSlides.indexOf(this.galImageUrl));
      this.lbZoom = false;
      this.lbOpen = true;
    },
    closeLightbox() {
      this.lbOpen = false;
      this.lbZoom = false;
    },
    lbStep(dir) {
      const n = this.lbSlides.length;
      if (n < 2) return;
      this.lbPos = (this.lbPos + dir + n) % n;
    },
    setLbOrigin(clientX, clientY) {
      const el = this.$refs.lbStage;
      if (!el) return;
      const r = el.getBoundingClientRect();
      const clamp = (v) => Math.min(100, Math.max(0, v));
      el.style.setProperty('--zx', `${clamp(((clientX - r.left) / r.width) * 100)}%`);
      el.style.setProperty('--zy', `${clamp(((clientY - r.top) / r.height) * 100)}%`);
    },
    // Clic: amplía en el punto tocado; otro clic vuelve al tamaño normal
    toggleLbZoom(e) {
      if (this.lbTouch && this.lbTouch.moved) return;
      this.setLbOrigin(e.clientX, e.clientY);
      this.lbZoom = !this.lbZoom;
    },
    // Con zoom, la imagen sigue al mouse para recorrerla
    onLbMove(e) {
      if (this.lbZoom) this.setLbOrigin(e.clientX, e.clientY);
    },
    onLbTouchStart(e) {
      const t = e.touches[0];
      this.lbTouch = { x: t.clientX, y: t.clientY, moved: false };
    },
    onLbTouchMove(e) {
      if (!this.lbTouch) return;
      const t = e.touches[0];
      if (Math.abs(t.clientX - this.lbTouch.x) > 8 || Math.abs(t.clientY - this.lbTouch.y) > 8) this.lbTouch.moved = true;
      if (!this.lbZoom) return;
      e.preventDefault();
      this.setLbOrigin(t.clientX, t.clientY);
    },
    onLbTouchEnd(e) {
      const start = this.lbTouch;
      if (!start) return;
      // Deslizar sin zoom cambia de foto
      if (!this.lbZoom && start.moved) {
        const dx = e.changedTouches[0].clientX - start.x;
        if (Math.abs(dx) > 40) this.lbStep(dx < 0 ? 1 : -1);
      }
      setTimeout(() => {
        this.lbTouch = null;
      }, 0);
    },
    // ===== Productos relacionados =====
    openRelated(p) {
      // Ya no se vuelve con "atrás": el botón lleva directo a la grilla
      this.cameFromCatalog = false;
      this.$router.push({ name: 'Public Catalog Product', params: { token: this.token, productId: p.matid } });
    },
    updateRelArrows() {
      const el = this.$refs.relTrack;
      if (!el) return;
      this.relCanLeft = el.scrollLeft > 2;
      this.relCanRight = el.scrollLeft + el.clientWidth < el.scrollWidth - 2;
    },
    scrollRelated(dir) {
      const el = this.$refs.relTrack;
      if (el) el.scrollBy({ left: dir * el.clientWidth * 0.8, behavior: 'smooth' });
    },
    // ===== Detalle de producto =====
    abrirProducto(p) {
      this.catalogScrollY = window.scrollY;
      this.cameFromCatalog = true;
      this.$router.push({ name: 'Public Catalog Product', params: { token: this.token, productId: p.matid } });
    },
    // Vuelve a la grilla: con historial se usa "atrás" para no duplicar entradas
    goBack() {
      if (this.cameFromCatalog) {
        this.cameFromCatalog = false;
        this.$router.back();
      } else {
        this.$router.push({ name: 'Public Catalog', params: { token: this.token } });
      }
    },
    colorKey(v) {
      const name = (v.descolor || '').trim().toLowerCase();
      return name ? `n${name}` : '_none';
    },
    // Tallas numéricas de menor a mayor; las de letras en el orden habitual
    compareSizes(a, b) {
      const order = ['XXS', 'XS', 'S', 'M', 'L', 'XL', 'XXL', '2XL', 'XXXL', '3XL'];
      const sa = String(a.destalla || '').trim().toUpperCase();
      const sb = String(b.destalla || '').trim().toUpperCase();
      const na = parseFloat(sa.replace(',', '.'));
      const nb = parseFloat(sb.replace(',', '.'));
      if (!isNaN(na) && !isNaN(nb)) return na - nb;
      const ia = order.indexOf(sa);
      const ib = order.indexOf(sb);
      if (ia >= 0 && ib >= 0) return ia - ib;
      return sa.localeCompare(sb, 'es', { numeric: true });
    },
    // Estado inicial del detalle: galería en la foto que se veía en la tarjeta
    resetDetail() {
      this.galDead = [];
      this.galZoom = false;
      this.pdpQty = 1;
      this.pdpVariantId = null;
      this.pdpColorKey = null;
      const p = this.detailProduct;
      this.galPos = p ? this.posFoto(p) : 0;
      this.initSeleccion();
    },
    // Primer color con stock y su talla si es la única
    initSeleccion() {
      if (this.pdpCargandoVariantes) return;
      if (this.pdpHasColors) {
        const first = this.pdpColors.find((c) => !c.soldOut) || this.pdpColors[0];
        if (first) this.selectColor(first.key);
      } else {
        this.autoPickSize();
      }
    },
    // Con una sola talla disponible (o sin tallas) se elige sola
    autoPickSize() {
      const disponibles = this.pdpSizes.filter((v) => !this.varianteAgotada(v));
      if (disponibles.length === 1 && (this.pdpSizes.length === 1 || !this.pdpHasSizes)) {
        this.pdpVariantId = disponibles[0].serialid;
      }
    },
    selectColor(key) {
      const prevSize = this.pdpVariant?.destalla;
      this.pdpColorKey = key;
      // Se conserva la misma talla en el nuevo color si está disponible
      const same = this.pdpSizes.find((v) => v.destalla === prevSize && !this.varianteAgotada(v));
      this.pdpVariantId = same ? same.serialid : null;
      if (!same) this.autoPickSize();
      this.pdpQty = 1;
    },
    selectSize(v) {
      if (this.varianteAgotada(v)) return;
      this.pdpVariantId = v.serialid;
      this.pdpQty = 1;
    },
    pdpQtyInput(e) {
      let n = parseInt(String(e.target.value).replace(/\D/g, ''), 10);
      if (isNaN(n) || n < 1) n = 1;
      n = Math.min(n, Math.max(1, this.pdpMax));
      this.pdpQty = n;
      e.target.value = n;
    },
    addFromDetail() {
      const p = this.detailProduct;
      const row = this.pdpRow;
      if (!p || !row || this.pdpMax <= 0) return;
      const qty = Math.min(this.pdpQty, this.pdpMax);
      this.agregarDirecto(p, row.single ? null : row, qty, this.galImageUrl);
      this.pdpQty = 1;
      this.openCart();
      this.fabBump = true;
      setTimeout(() => {
        this.fabBump = false;
      }, 600);
    },
    lineKey(producto, row) {
      return `${producto.matid}_${row.single ? '0' : String(row.serialid)}`;
    },
    // Inserta o acumula una línea agrupada por matid + serialid
    agregarDirecto(producto, serial, qty, imagen) {
      const nroserial = serial ? String(serial.serialid) : '0';
      const key = `${producto.matid}_${nroserial}`;
      const maxQty = serial ? parseInt(serial.saldo, 10) || 0 : parseInt(producto.existencia, 10) || 0;
      const existente = this.cart.find((i) => i.key === key);
      if (existente) {
        existente.qty = maxQty > 0 ? Math.min(existente.qty + qty, maxQty) : existente.qty + qty;
      } else {
        this.cart.push({
          key,
          matid: producto.matid,
          serialid: serial ? serial.serialid : null,
          nroserial,
          nombre: producto.descrip,
          detalle: serial
            ? [serial.destalla, serial.descolor].filter(Boolean).join(' / ')
            : '',
          // Precio con descuento; el servidor lo recalcula al registrar el pedido
          precio: this.precioFinal(producto),
          imagen: imagen || this.fotoActual(producto),
          qty,
          maxQty,
        });
      }
    },
    openCart() {
      this.cartOpen = true;
    },
    closeCart() {
      this.cartOpen = false;
    },
    cambiarCantidad(item, delta) {
      const nueva = item.qty + delta;
      if (nueva <= 0) {
        this.eliminarLinea(item);
        return;
      }
      if (delta > 0 && item.maxQty > 0 && nueva > item.maxQty) return;
      item.qty = nueva;
    },
    lineInput(item, e) {
      let n = parseInt(String(e.target.value).replace(/\D/g, ''), 10);
      if (isNaN(n)) n = 0;
      if (item.maxQty > 0) n = Math.min(n, item.maxQty);
      item.qty = n;
      e.target.value = n;
      if (n === 0) this.eliminarLinea(item);
    },
    eliminarLinea(item) {
      this.cart = this.cart.filter((i) => i.key !== item.key);
    },
    async enviarPedido() {
      this.orderError = '';
      if (this.cartCount < MIN_TOTAL_UNIDADES) {
        this.orderError = `El pedido mínimo es de ${MIN_TOTAL_UNIDADES} unidades (llevas ${this.cartCount}).`;
        return;
      }
      if (!this.formCompleta) return;
      this.sending = true;
      try {
        const res = await catalogService.sendPedido(this.token, {
          items: this.cart.map((i) => ({ matid: i.matid, serialid: i.serialid, qty: i.qty })),
          cliente: {
            nombre: this.form.nombre,
            departamento: this.form.departamento,
            ciudad: this.form.ciudad,
            direccion: this.form.direccion,
          },
        });
        window.open(res.data.whatsapp_url, '_blank');
      } catch (e) {
        this.orderError =
          e.response?.data?.message || 'No se pudo enviar el pedido. Intenta de nuevo.';
      } finally {
        this.sending = false;
      }
    },
  },
};
</script>

