.catmenu__item--active,
.catmenu__item--active:hover {
  background: var(--brand);
  color: #fff;
}
.catmenu__count {
  font-size: 12px;
  font-weight: 600;
  color: var(--ink-55);
  flex-shrink: 0;
}
.catmenu__item--active .catmenu__count {
  color: rgba(255, 255, 255, 0.75);
}

/* ===== Banners de promoción ===== */
.banner {
  position: relative;
  overflow: hidden;
  background: #f6f6f6;
  touch-action: pan-y;
}
/* Las diapositivas se apilan en la misma celda: el alto lo da la imagen más alta */
.banner__track {
  display: grid;
}
.banner__slide {
  grid-area: 1 / 1;
  align-self: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.5s;
}
.banner__slide--active {
  opacity: 1;
  pointer-events: auto;
}
.banner__slide img {
  width: 100%;
  height: auto;
  display: block;
}

/* ===== 3) Título de colección ===== */
.collection {
  flex: 1;
}
/* El espacio superior va en el contenido: el banner queda pegado a la barra */
.collection > .container-x {
  padding-top: 36px;
}
.collection__head {
  text-align: center;
  margin-bottom: 24px;
}
.collection__head h1 {
  margin: 0;
  font-size: 28px;
  font-weight: 600;
  color: var(--ink);
}
.collection__head p {
  margin: 6px 0 0;
  font-size: 13.5px;
  color: var(--ink-55);
}
.collection__head p strong {
  font-weight: 600;
  color: var(--ink);
}

/* ===== 4) Toolbar ===== */
.toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 20px;
}
.toolbar__count {
  font-size: 13px;
  color: var(--ink-55);
}
.toolbar__sort {
  display: flex;
  align-items: center;
  gap: 8px;
}
.toolbar__label {
  font-size: 12.5px;
  color: var(--ink-55);
}
.select-wrap {
  position: relative;
  display: inline-flex;
}
.select-wrap select {
  appearance: none;
  -webkit-appearance: none;
  border: 1px solid rgba(18, 18, 18, 0.2);
  border-radius: 8px;
  background: #fff;
  padding: 8px 30px 8px 12px;
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  color: var(--ink);
  cursor: pointer;
  outline: none;
}
.select-wrap i {
  position: absolute;
  right: 10px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 10px;
  color: var(--ink-55);
  pointer-events: none;
}

/* ===== 5) Chips de categorías ===== */
.cat-chips-wrap {
  position: relative;
  margin: 0 -16px 20px;
}
.cat-chips {
  display: flex;
  flex-wrap: nowrap;
  gap: 8px;
  overflow-x: auto;
  overscroll-behavior-x: contain;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  padding: 0 16px 2px;
}
.cat-chips::-webkit-scrollbar {
  display: none;
}
@media (min-width: 768px) {
  .cat-chips-wrap {
    margin-left: -32px;
    margin-right: -32px;
  }
  .cat-chips {
    padding-left: 32px;
    padding-right: 32px;
  }
}
/* Flecha con degradado: indica que hay más categorías hacia ese lado */
.cat-chips-arrow {
  position: absolute;
  top: 0;
  bottom: 2px;
  z-index: 2;
  width: 56px;
  border: none;
  padding: 0;
  display: flex;
  align-items: center;
  cursor: pointer;
}
.cat-chips-arrow--prev {
  left: 0;
  justify-content: flex-start;
  padding-left: 8px;
  background: linear-gradient(to right, #fff 45%, rgba(255, 255, 255, 0));
}
.cat-chips-arrow--next {
  right: 0;
  justify-content: flex-end;
  padding-right: 8px;
  background: linear-gradient(to left, #fff 45%, rgba(255, 255, 255, 0));
}
.cat-chips-arrow span {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  border: 1px solid rgba(18, 18, 18, 0.2);
  background: #fff;
  color: var(--ink);
  font-size: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  transition: background 0.15s, color 0.15s;
}
.cat-chips-arrow:hover span {
  background: var(--ink);
  color: #fff;
}
.cat-chip {
  flex-shrink: 0;
  white-space: nowrap;
  border: 1px solid rgba(18, 18, 18, 0.2);
  background: #fff;
  color: var(--ink);
  border-radius: 999px;
  padding: 7px 16px;
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s, color 0.15s;
}
.cat-chip:hover {
  border-color: var(--ink);
}
.cat-chip--active {
  background: var(--ink);
  border-color: var(--ink);
  color: #fff;
}

/* ===== 6) Grilla y tarjeta de producto ===== */
.pgrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px 12px;
}
.pcard {
  display: flex;
  flex-direction: column;
  cursor: pointer;
}
.pcard--soldout {
  cursor: default;
}
.pcard__media {
  position: relative;
  aspect-ratio: 3 / 4;
  border-radius: 12px;
  overflow: hidden;
  background: #f6f6f6;
  transition: box-shadow 0.25s;
}
.pcard:hover .pcard__media {
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.08);
}
.pcard__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transform-origin: var(--zx, 50%) var(--zy, 50%);
  transition: transform 0.35s;
}
/* Zoom al pasar el mouse (solo en dispositivos con puntero) */
@media (hover: hover) and (pointer: fine) {
  .pcard__media {
    cursor: zoom-in;
  }
  .pcard:hover .pcard__media img {
    transform: scale(1.6);
  }
}
.slidefade-enter-active,
.slidefade-leave-active {
  transition: opacity 0.25s;
}
.slidefade-enter-from,
.slidefade-leave-to {
  opacity: 0;
}
.pcard__placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 38px;
  color: rgba(18, 18, 18, 0.15);
}
.badge {
  position: absolute;
  top: 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 5px 10px;
  z-index: 1;
}
.badge--soldout {
  left: 10px;
  background: #fff;
  color: var(--ink);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}
.badge--sale {
  left: 10px;
  background: var(--brand);
  color: #fff;
}
.badge--stock {
  right: 10px;
  background: rgba(18, 18, 18, 0.72);
  color: #fff;
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
}
.pcard__info {
  padding: 12px 2px 0;
  text-align: left;
}
.pcard__title {
  margin: 0;
  font-size: 13.5px;
  font-weight: 500;
  line-height: 1.45;
  color: var(--ink);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.pcard__price-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 4px;
}
.pcard__price {
  font-size: 14.5px;
  font-weight: 700;
}
.tag {
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  border: 1px solid;
  padding: 1px 8px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
}
.tag--cop {
  background: #eeeef4;
  color: #5c5c72;
  border-color: #d6d6e0;
}
.tag--usd {
  background: #e8f5ec;
  color: #1a7a3c;
  border-color: #bfe3cb;
}
.pcard__ref {
  margin: 2px 0 0;
  font-size: 11.5px;
  color: var(--ink-55);
}
.price-old {
  font-size: 11.5px;
  color: var(--ink-55);
}
.tag--sale {
  background: #e7efec;
  color: var(--brand);
  border-color: #b9cfc7;
}

/* Carrusel de la tarjeta (flechas y puntos) */
.pcard__arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 3;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  border: 1px solid var(--line);
  color: var(--ink);
  font-size: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.2s, background 0.2s, color 0.2s;
}
.pcard__arrow--prev {
  left: 8px;
}
.pcard__arrow--next {
  right: 8px;
}
.pcard:hover .pcard__arrow {
  opacity: 1;
}
.pcard__arrow:hover {
  background: var(--ink);
  color: #fff;
}
@media (hover: none) {
  .pcard__arrow {
    opacity: 1;
  }
}
.pcard__dots {
  position: absolute;
  bottom: 10px;
  left: 0;
  right: 0;
  display: flex;
  justify-content: center;
  gap: 5px;
  z-index: 3;
}
.pcard__dot {
  width: 6px;
  height: 6px;
  border-radius: 999px;
  border: none;
  padding: 0;
  background: rgba(255, 255, 255, 0.85);
  box-shadow: 0 1px 3px rgba(18, 18, 18, 0.3);
  cursor: pointer;
  transition: background 0.2s, width 0.2s;
}
.pcard__dot--active {
  background: var(--ink);
  width: 14px;
}

/* Flechas grandes (banner y galería del detalle) */
.gal-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 2;
  width: 36px;
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  color: var(--ink);
  font-size: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, color 0.2s;
}
.gal-arrow--prev {
  left: 10px;
}
.gal-arrow--next {
  right: 10px;
}
.gal-arrow:hover {
  background: var(--ink);
  color: #fff;
}

/* ===== 7) Estados ===== */
.skeleton {
  pointer-events: none;
}
.skeleton__media {
  width: 100%;
  aspect-ratio: 3 / 4;
  border-radius: 12px;
  background: linear-gradient(100deg, #f0f0f0 40%, #f7f7f7 50%, #f0f0f0 60%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite linear;
}
.skeleton__line {
  height: 11px;
  border-radius: 6px;
  margin-top: 12px;
  background: linear-gradient(100deg, #f0f0f0 40%, #f7f7f7 50%, #f0f0f0 60%);
  background-size: 200% 100%;
  animation: shimmer 1.4s infinite linear;
}
@keyframes shimmer {
  0% {
    background-position: 120% 0;
  }
  100% {
    background-position: -80% 0;
  }
}
.shop-state {
  text-align: center;
  padding: 72px 20px;
  color: var(--ink-55);
}
.shop-state__icon {
  font-size: 34px;
  opacity: 0.5;
}
.shop-state p {
  margin: 12px 0 0;
  font-size: 13.5px;
  color: var(--ink-75);
}
.shop-state__link {
  border: none;
  background: none;
  padding: 0;
  margin-top: 8px;
  font-size: 13px;
  font-family: inherit;
  color: var(--ink);
  text-decoration: underline;
  cursor: pointer;
}
.shop-state__link:hover {
  color: var(--brand-dark);
}

/* ===== 8) Footer ===== */
.shop-footer {
  border-top: 1px solid var(--line);
  margin-top: 48px;
  padding: 40px 20px 48px;
  text-align: center;
}
.shop-footer__logo {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid var(--line);
  padding: 2px;
  object-fit: cover;
}
.shop-footer__name {
  margin: 12px 0 0;
  font-size: 15px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.shop-footer__tagline {
  margin: 6px 0 0;
  font-size: 12.5px;
  color: var(--ink-55);
}
.shop-footer__copy {
  margin: 14px 0 0;
  font-size: 11.5px;
  color: rgba(18, 18, 18, 0.4);
}

/* ===== 9) Drawer del carrito ===== */
.cart-overlay {
  position: fixed;
  inset: 0;
  background: rgba(18, 18, 18, 0.45);
  z-index: 200;
}
.ofade-enter-active,
.ofade-leave-active {
  transition: opacity 0.2s;
}
.ofade-enter-from,
.ofade-leave-to {
  opacity: 0;
}
.cart {
  position: fixed;
  right: 0;
  top: 0;
  width: 100%;
  max-width: 430px;
  height: 100vh;
  height: 100dvh;
  background: #fff;
  z-index: 201;
  display: flex;
  flex-direction: column;
  box-shadow: -8px 0 32px rgba(0, 0, 0, 0.14);
  transform: translateX(100%);
  transition: transform 0.28s;
}
.cart--open {
  transform: translateX(0);
}
.cart__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  flex-shrink: 0;
}
.cart__title {
  margin: 0;
  font-size: 17px;
  font-weight: 600;
  color: var(--ink);
}
.icon-btn {
  width: 34px;
  height: 34px;
  border: none;
  border-radius: 50%;
  background: transparent;
  color: var(--ink);
  font-size: 15px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.icon-btn:hover {
  background: rgba(18, 18, 18, 0.06);
}
.cart__empty {
  text-align: center;
  padding: 48px 20px;
}
.cart__empty-icon {
  font-size: 34px;
  opacity: 0.4;
}
.cart__empty p {
  margin: 12px 0 16px;
  font-size: 13.5px;
  color: var(--ink-55);
}
.cart__items {
  flex: 1;
  overflow-y: auto;
  padding: 4px 20px;
}
.cart__item {
  display: flex;
  gap: 12px;
  padding: 16px 0;
  border-bottom: 1px solid rgba(18, 18, 18, 0.06);
}
.cart__item:last-child {
  border-bottom: none;
}
.cart__thumb {
  width: 68px;
  height: 88px;
  flex-shrink: 0;
  border-radius: 10px;
  background: #f6f6f6;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  color: rgba(18, 18, 18, 0.15);
  font-size: 22px;
}
.cart__thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cart__item-info {
  flex: 1;
  min-width: 0;
}
.cart__item-name {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  line-height: 1.4;
}
.cart__item-variant {
  display: inline-flex;
  margin-top: 4px;
  background: #f4f4f4;
  border-radius: 999px;
  padding: 3px 8px;
  font-size: 10.5px;
  font-weight: 600;
  color: var(--ink-75);
}
.cart__item-price {
  margin: 4px 0 0;
  font-size: 11.5px;
  color: var(--ink-55);
}
.cart__item-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 8px;
}
.cart__item-remove {
  border: none;
  background: none;
  padding: 0;
  font-size: 11.5px;
  font-family: inherit;
  color: var(--ink-55);
  text-decoration: underline;
  cursor: pointer;
}
.cart__item-remove:hover {
  color: #b3261e;
}
.cart__item-total {
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}
.cart__foot {
  border-top: 1px solid var(--line);
  padding: 16px 20px 20px;
  max-height: 62vh;
  overflow-y: auto;
  flex-shrink: 0;
}
.cart__minbar-rail {
  height: 3px;
  border-radius: 999px;
  background: #eee;
  overflow: hidden;
}
.cart__minbar-fill {
  height: 100%;
  border-radius: 999px;
  background: var(--brand);
  transition: width 0.3s;
}
.cart__minbar-text {
  margin: 6px 0 0;
  font-size: 10.5px;
  color: var(--ink-55);
}
.cart__minbar-text--ok {
  color: #1a7f4b;
}
.cart__subtotal {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 14px;
}
.cart__subtotal-label {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-55);
}
.cart__subtotal-value {
  font-size: 18px;
  font-weight: 700;
  display: flex;
  align-items: center;
  gap: 6px;
}
.cart__subtotal-value .tag {
  font-size: 9.5px;
}
.cart__shipping {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 6px;
}
.cart__shipping-value {
  font-size: 12.5px;
  font-weight: 600;
  color: var(--ink-75);
}
.cart__note {
  margin: 8px 0 0;
  font-size: 11.5px;
  color: var(--ink-55);
}
.cart__note + .cart__note {
  margin-top: 4px;
}
.cart__note i {
  width: 16px;
  text-align: center;
  margin-right: 2px;
}
.cart__note + .cart__form {
  margin-top: 12px;
}
.cart__form {
  display: grid;
  gap: 8px;
}
.cart__form-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}
.field {
  width: 100%;
  border: 1px solid rgba(18, 18, 18, 0.25);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 13px;
  font-family: inherit;
  color: var(--ink);
  background: #fff;
  outline: none;
  transition: border-color 0.15s;
}
.field:focus {
  border-color: var(--ink);
}
.field:disabled {
  background: #f6f6f6;
  color: var(--ink-55);
  cursor: not-allowed;
}
.cart__error {
  margin: 0;
  font-size: 12px;
  color: #b3261e;
}

/* Botones oscuros */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-family: inherit;
  transition: opacity 0.15s, background 0.15s;
}
.btn--dark {
  background: var(--ink);
  color: #fff;
  padding: 14px 22px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.btn--dark:hover:not(:disabled) {
  background: #000;
}
.btn--dark:disabled {
  background: #e5e5e5;
  color: #9a9a9a;
  cursor: not-allowed;
}
.btn--block {
  width: 100%;
}

/* ===== Stepper compartido ===== */
.stepper {
  display: inline-flex;
  align-items: center;
  border: 1px solid rgba(18, 18, 18, 0.2);
  border-radius: 8px;
  overflow: hidden;
}
.stepper button {
  width: 28px;
  height: 28px;
  border: none;
  background: transparent;
  color: var(--ink);
  font-size: 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.15s;
}
.stepper button:hover:not(:disabled) {
  background: rgba(18, 18, 18, 0.06);
}
.stepper button:disabled {
  opacity: 0.35;
  cursor: default;
}
.stepper__num {
  min-width: 30px;
  text-align: center;
  font-size: 12.5px;
  font-weight: 700;
}

/* Galería del detalle de producto */
.pgal {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 5;
  max-height: 52vh;
  background: #f6f6f6;
  overflow: hidden;
  touch-action: pan-y;
}
.pgal img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  display: block;
  transform-origin: var(--zx, 50%) var(--zy, 50%);
  transition: transform 0.25s;
}
@media (hover: hover) and (pointer: fine) {
  .pgal {
    cursor: zoom-in;
  }
  .pgal:hover img {
    transform: scale(2.2);
  }
}
.pgal--zoom {
  touch-action: none;
}
.pgal--zoom img {
  transform: scale(2.2);
}
.pgal__zoom {
  position: absolute;
  bottom: 10px;
  left: 10px;
  z-index: 2;
  width: 36px;
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  color: var(--ink);
  font-size: 13px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, color 0.2s;
}
.pgal__zoom:hover,
.pgal--zoom .pgal__zoom {
  background: var(--ink);
  color: #fff;
