<template>
  <div class="card">
    <div class="pb-0 card-header mb-0">
      <h5>{{ title }}</h5>
      <p class="text-sm">
        <span class="font-weight-bold">{{ detail1 }}</span>
        {{ detail2 }}
      </p>
    </div>
    <div class="p-3 card-body">
      <div class="chart">
        <canvas ref="canvas" class="chart-canvas" height="300"></canvas>
      </div>
    </div>
  </div>
</template>

<script>
import Chart from "chart.js/auto";

const AXIS_COLOR = "#8392ab";
const formatMoney = (value) =>
  "$ " + (parseFloat(value) || 0).toLocaleString("es-CO", { maximumFractionDigits: 0 });

export default {
  name: "gradient-line-chart",
  props: {
    title: {
      type: String,
      default: "Ventas y Compras",
    },
    detail1: {
      type: String,
      default: "",
    },
    detail2: {
      type: String,
      default: "",
    },
    dateFrom: {
      type: String,
      default: "",
    },
    dateTo: {
      type: String,
      default: "",
    },
  },
  computed: {
    rangeKey() {
      return `${this.dateFrom}|${this.dateTo}`;
    },
  },
  watch: {
    rangeKey() {
      this.fetchSeries();
    },
  },
  created() {
    // Fuera de data(): Chart.js no funciona con objetos reactivos
    this.chart = null;
    this.requestId = 0;
  },
  methods: {
    async fetchSeries() {
      const requestId = ++this.requestId;
      const params = this.dateFrom && this.dateTo
        ? { date_from: this.dateFrom, date_to: this.dateTo }
        : {};
      try {
        const response = await this.$store.dispatch("analitycs/getYear", params);
        // Si cambió el rango mientras cargaba, esta respuesta ya no aplica
        if (requestId !== this.requestId) return;
        this.renderChart(Array.isArray(response?.data) ? response.data : []);
      } catch (e) {
        if (requestId === this.requestId) this.renderChart([]);
      }
    },
    renderChart(rows) {
      const canvas = this.$refs.canvas;
      if (!canvas) return;

      if (this.chart) this.chart.destroy();

      const barStyle = { maxBarThickness: 24, borderRadius: 4, barPercentage: 0.9, categoryPercentage: 0.8 };

      this.chart = new Chart(canvas.getContext("2d"), {
        type: "bar",
        data: {
          labels: rows.map((row) => row.mes),
          datasets: [
            { label: "Ventas", backgroundColor: "#1f77d0", data: rows.map((row) => row.ventas), ...barStyle },
            { label: "Compras", backgroundColor: "#e0782f", data: rows.map((row) => row.compras), ...barStyle },
          ],
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: { display: true, labels: { color: AXIS_COLOR, boxWidth: 12 } },
            tooltip: {
              callbacks: {
                label: (context) => `${context.dataset.label}: ${formatMoney(context.raw)}`,
              },
            },
          },
          interaction: { intersect: false, mode: "index" },
          scales: {
            y: {
              beginAtZero: true,
              grid: { drawBorder: false, drawTicks: false, color: "rgba(131, 146, 171, 0.2)" },
              ticks: { color: AXIS_COLOR, padding: 10, font: { size: 12 }, callback: formatMoney },
            },
            x: {
              grid: { drawBorder: false, display: false, drawTicks: false },
              ticks: { color: AXIS_COLOR, padding: 10, font: { size: 12 } },
            },
          },
        },
      });
    },
  },
  mounted() {
    this.fetchSeries();
  },
  beforeUnmount() {
    if (this.chart) this.chart.destroy();
  },
};
</script>
