<template>
  <div class="py-4 container-fluid">
    <div class="row">
      <div class="col-12">
        <div class="card">
          <div class="card-header pb-0">
            <div class="d-flex justify-content-between align-items-center mb-2">
              <h6 class="mb-0">Categorías</h6>
              <div>
                <button class="btn btn-outline-primary btn-sm me-2" @click="openOrden">
                  Organizar <i class="fa fa-sort ms-1"></i>
                </button>
                <button class="btn btn-primary btn-sm" @click="openForm">
                  Agregar <i class="fa fa-plus ms-1"></i>
                </button>
              </div>
            </div>
            <div class="row">
              <div class="col-md-6 mb-3">
                <label for="searchQuery" class="mb-1">Buscar</label>
                <input type="text" v-model="searchQuery" id="searchQuery" class="form-control"
                  placeholder="Buscar..." @input="fetchData(null)" />
              </div>
            </div>
          </div>
          <div class="card-body px-0 pt-0 pb-2">
            <div class="table-responsive p-0">
              <table class="table align-items-center mb-0">
                <thead>
                  <tr>
                    <th class="text-uppercase text-secondary text-xxs font-weight-bolder opacity-7">Código</th>
                    <th class="text-uppercase text-secondary text-xxs font-weight-bolder opacity-7">Nombre</th>
                    <th class="text-uppercase text-secondary text-xxs font-weight-bolder opacity-7">Categoría padre</th>
                    <th class="text-center text-uppercase text-secondary text-xxs font-weight-bolder opacity-7">Opciones</th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="value in page.data" :key="value.id">
                    <td class="align-middle text-sm">{{ value.code || '-' }}</td>
                    <td class="align-middle text-sm">{{ value.name }}</td>
                    <td class="align-middle text-sm">{{ parentName(value.parent_id) }}</td>
                    <td class="align-middle text-center">
                      <a @click="editItem(value)" class="text-secondary font-weight-bold text-xs cursor-pointer"
                        data-toggle="tooltip" data-original-title="Editar registro">
                        <i class="fa fa-pencil-alt"></i>
                      </a>
                      <a @click="deleteItem(value.id)" class="text-secondary font-weight-bold text-xs cursor-pointer"
                        style="margin-left: 15px;" data-toggle="tooltip" data-original-title="Eliminar registro">
                        <i class="fa fa-trash"></i>
                      </a>
                    </td>
                  </tr>
                  <tr v-if="page.data && page.data.length === 0">
                    <td colspan="4" class="text-center text-xxs">No hay registros disponibles</td>
                  </tr>
                </tbody>
              </table>

              <!-- Paginación -->
              <div class="pagination p-3">
                <a v-for="link in page.links" :key="link.label" class="page-item cursor-pointer"
                  @click="fetchData(link.url)" :disabled="!link.url || link.active"
                  :class="{ 'active': link.label === String(page.current_page) }">
                  <span v-html="link.label"></span>
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Modal Organizar: define el orden de las categorías en el catálogo -->
    <div class="modal fade" id="ModalCategoriaOrden" tabindex="-1" role="dialog">
      <div class="modal-dialog modal-dialog-scrollable">
        <div class="modal-content card">
          <div class="modal-header">
            <h5 class="modal-title">Organizar categorías</h5>
            <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
          </div>
          <div ref="ordenBody" class="modal-body">
            <p class="text-sm mb-3">
              Arrastra las categorías para definir el orden en que el catálogo las muestra con sus productos.
              Las subcategorías se ordenan dentro de su categoría principal.
            </p>
            <ul ref="ordenFilas" class="list-group">
              <li v-for="fila in ordenArbol" :key="fila.id" :data-orden-id="fila.id"
                class="list-group-item d-flex justify-content-between align-items-center py-2 orden-fila"
                :class="{
                  'orden-fila--grupo': arrastrandoGrupo.includes(fila.id),
                  'orden-fila--activa': arrastrandoId === fila.id,
                }"
                @pointerdown="iniciarArrastre($event, fila.id)">
                <span class="text-sm" :class="{ 'font-weight-bold': fila.nivel === 0 }"
                  :style="{ paddingLeft: fila.nivel * 20 + 'px' }">
                  <i class="fa fa-grip-vertical text-secondary me-2 px-1 orden-asa"></i>{{ fila.name }}
                </span>
                <span class="text-nowrap">
                  <button type="button" class="btn btn-link btn-sm text-secondary mb-0 px-2" :disabled="fila.primero"
                    :aria-label="'Subir ' + fila.name" @click="moverCategoria(fila.id, -1)">
                    <i class="fa fa-arrow-up"></i>
                  </button>
                  <button type="button" class="btn btn-link btn-sm text-secondary mb-0 px-2" :disabled="fila.ultimo"
                    :aria-label="'Bajar ' + fila.name" @click="moverCategoria(fila.id, 1)">
                    <i class="fa fa-arrow-down"></i>
                  </button>
                </span>
              </li>
              <li v-if="ordenArbol.length === 0" class="list-group-item text-center text-xxs">
                No hay registros disponibles
              </li>
            </ul>
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
            <button type="button" class="btn btn-primary" :disabled="guardandoOrden || ordenArbol.length === 0"
              @click="guardarOrden"><i class="fa fa-save"></i> Guardar</button>
          </div>
        </div>
      </div>
    </div>

    <!-- Modal Formulario -->
    <div class="modal fade" id="ModalCategoriaForm" tabindex="-1" role="dialog">
      <div class="modal-dialog">
        <div class="modal-content card">
          <div class="modal-header">
            <h5 class="modal-title">{{ isEditing ? 'Editar Categoría' : 'Agregar Categoría' }}</h5>
            <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
          </div>
          <div class="modal-body">
            <form @submit.prevent="submitForm">
              <div class="mb-3">
                <label class="form-label">Código</label>
                <input type="text" v-model="form.code" class="form-control" placeholder="Código">
              </div>
              <div class="mb-3">
                <label class="form-label">Nombre <span class="text-danger">*</span></label>
                <input type="text" v-model="form.name" class="form-control" placeholder="Categoría" required>
              </div>
              <div class="mb-3">
                <label class="form-label">Categoría padre</label>
                <select v-model="form.parent_id" class="form-select">
                  <option value="" selected>Seleccionar</option>
                  <option v-for="p in allCategories" :key="p.id" :value="p.id">{{ p.name }}</option>
                </select>
              </div>
              <div class="mb-3">
                <label class="form-label">Descripción</label>
                <textarea v-model="form.description" class="form-control" rows="2" placeholder="Descripción (opcional)"></textarea>
              </div>
            </form>
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-secondary" @click="cancelEdit">Cancelar</button>
            <button type="button" class="btn btn-primary" @click="submitForm"><i class="fa fa-save"></i> Guardar</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import * as bootstrap from 'bootstrap';
import Swal from 'sweetalert2';

export default {
  name: "SettingsCategorias",
  data() {
    return {
      form: { id: 0, code: '', name: '', description: '', parent_id: '' },
      searchQuery: '',
      isEditing: false,
      perPage: 10,
      page: { data: [], current_page: 1, from: 0, to: 0, total: 0, last_page: 1, prev_page_url: null, next_page_url: null, links: [] },
      allCategories: [],
      modalInstance: null,
      ordenLista: [],
      ordenModal: null,
      guardandoOrden: false,
      arrastrandoId: null,
      arrastrandoGrupo: [],
      arrastre: null,
    };
  },
  computed: {
    // Lista plana en forma de árbol: cada categoría seguida de sus subcategorías
    ordenArbol() {
      const hijos = new Map();
      this.ordenLista.forEach((c) => {
        const padre = c.parent_id || null;
        if (!hijos.has(padre)) hijos.set(padre, []);
        hijos.get(padre).push(c);
      });
      const filas = [];
      const agregar = (padre, nivel) => {
        const hermanas = hijos.get(padre) || [];
        hermanas.forEach((c, i) => {
          filas.push({ id: c.id, name: c.name, nivel, primero: i === 0, ultimo: i === hermanas.length - 1 });
          agregar(c.id, nivel + 1);
        });
      };
      agregar(null, 0);
      return filas;
    },
  },
  mounted() {
    this.fetchData(null);
    this.fetchAll();
  },
  beforeUnmount() {
    this.finArrastre();
  },
  methods: {
    async fetchData(pageUrl = null) {
      const page = pageUrl ? new URL(pageUrl, window.location.origin).searchParams.get('page') || 1 : 1;
      try {
        const res = await this.$store.dispatch("categories/getPaginated", { page, per_page: this.perPage, search: this.searchQuery });
        this.page = res.data;
      } catch (e) { console.error(e); }
    },
    async fetchAll() {
      try {
        const res = await this.$store.dispatch("categories/getCategories");
        this.allCategories = res.data;
      } catch (e) { console.error(e); }
    },
    parentName(parentId) {
      if (!parentId) return '';
      const p = this.allCategories.find(c => c.id === parentId);
      return p ? p.name : '';
    },
    async openOrden() {
      try {
        const res = await this.$store.dispatch("categories/getCategories");
        this.ordenLista = [...res.data].sort((a, b) =>
          a.sort_order - b.sort_order || a.name.localeCompare(b.name, 'es')
        );
        this.ordenModal = bootstrap.Modal.getOrCreateInstance(document.getElementById('ModalCategoriaOrden'));
        this.ordenModal.show();
      } catch (e) {
        Swal.fire({ icon: 'error', title: 'Error', text: 'No se pudieron cargar las categorías' });
      }
    },
    hermanasDe(categoria) {
      return this.ordenLista.filter((c) => (c.parent_id || null) === (categoria.parent_id || null));
    },
    // Pone la categoría en la posición `destino` entre sus hermanas
    colocarCategoria(categoria, destino) {
      const hermanas = this.hermanasDe(categoria);
      const lista = [...this.ordenLista];
      const indices = hermanas.map((c) => lista.indexOf(c));
      const nuevas = hermanas.filter((c) => c !== categoria);
      nuevas.splice(destino, 0, categoria);
      nuevas.forEach((c, k) => {
        lista[indices[k]] = c;
      });
      this.ordenLista = lista;
    },
    // Mueve la categoría una posición: anterior (-1) o siguiente (1)
    moverCategoria(id, direccion) {
      const actual = this.ordenLista.find((c) => c.id === id);
      const hermanas = this.hermanasDe(actual);
      const destino = hermanas.indexOf(actual) + direccion;
      if (destino >= 0 && destino < hermanas.length) this.colocarConAnimacion(actual, destino);
    },
    filaOrden(id) {
      return this.$refs.ordenFilas.querySelector(`[data-orden-id="${id}"]`);
    },
    deslizar(el, desplazamiento) {
      el.animate(
        [{ transform: `translateY(${desplazamiento}px)` }, { transform: 'none' }],
        { duration: 180, easing: 'cubic-bezier(0.2, 0, 0, 1)' }
      );
    },
    // Reordena y desliza las filas desde donde estaban hasta su nuevo lugar
    colocarConAnimacion(categoria, destino) {
      const filas = [...this.$refs.ordenFilas.children];
      const antes = new Map(filas.map((el) => [el, el.getBoundingClientRect().top]));
      this.colocarCategoria(categoria, destino);
      this.$nextTick(() => {
        filas.forEach((el) => {
          if (this.arrastrandoGrupo.includes(Number(el.dataset.ordenId))) return;
          el.getAnimations().forEach((a) => a.cancel());
          const desplazamiento = antes.get(el) - el.getBoundingClientRect().top;
          if (desplazamiento) this.deslizar(el, desplazamiento);
        });
        if (this.arrastrandoId !== null) this.posicionarGrupo();
      });
    },
    // Con mouse se agarra toda la fila; en táctil solo el ícono, para poder hacer scroll
    iniciarArrastre(evento, id) {
      if (evento.button !== 0 || evento.target.closest('button')) return;
      if (evento.pointerType !== 'mouse' && !evento.target.closest('.orden-asa')) return;
      // La categoría arrastrada se lleva a sus subcategorías
      const arbol = this.ordenArbol;
      const inicio = arbol.findIndex((f) => f.id === id);
      let fin = inicio + 1;
      while (fin < arbol.length && arbol[fin].nivel > arbol[inicio].nivel) fin++;

      this.arrastrandoId = id;
      this.arrastrandoGrupo = arbol.slice(inicio, fin).map((f) => f.id);
      this.arrastre = {
        y: evento.clientY,
        agarre: evento.clientY - this.filaOrden(id).getBoundingClientRect().top,
        cuadro: requestAnimationFrame(this.pasoArrastre),
      };
      // Si la fila aún se deslizaba, esa animación taparía la posición del puntero
      this.arrastrandoGrupo.forEach((grupoId) => {
        this.filaOrden(grupoId).getAnimations().forEach((a) => a.cancel());
      });
      window.addEventListener('pointermove', this.moverArrastre);
      window.addEventListener('pointerup', this.finArrastre);
      window.addEventListener('pointercancel', this.finArrastre);
    },
    centroFila(id) {
      const caja = this.filaOrden(id).getBoundingClientRect();
      return caja.top + caja.height / 2;
    },
    moverArrastre(evento) {
      this.arrastre.y = evento.clientY;
    },
    // Corre en cada cuadro para que el scroll siga aunque el puntero esté quieto
    pasoArrastre() {
      if (this.arrastrandoId === null) return;
      const y = this.arrastre.y;
      const cuerpo = this.$refs.ordenBody;
      const caja = cuerpo.getBoundingClientRect();
      const zona = 48;
      if (y < caja.top + zona) cuerpo.scrollTop -= Math.ceil((caja.top + zona - y) / 4);
      else if (y > caja.bottom - zona) cuerpo.scrollTop += Math.ceil((y - caja.bottom + zona) / 4);

      const actual = this.ordenLista.find((c) => c.id === this.arrastrandoId);
      const hermanas = this.hermanasDe(actual);
      const posicion = hermanas.indexOf(actual);
      let destino = posicion;
      hermanas.forEach((c, i) => {
        if (i > posicion && y > this.centroFila(c.id)) destino = i;
        else if (i < posicion && destino === posicion && y < this.centroFila(c.id)) destino = i;
      });
      if (destino !== posicion) this.colocarConAnimacion(actual, destino);
      else this.posicionarGrupo();

      this.arrastre.cuadro = requestAnimationFrame(this.pasoArrastre);
    },
    // Pega la fila al puntero, sin dejarla salir del rango de sus hermanas
    posicionarGrupo() {
      const lider = this.filaOrden(this.arrastrandoId);
      lider.style.transform = '';
      const natural = lider.getBoundingClientRect().top;

      const hermanas = this.hermanasDe(this.ordenLista.find((c) => c.id === this.arrastrandoId));
      const minimo = this.filaOrden(hermanas[0].id).getBoundingClientRect().top;
      const maximo = this.filaOrden(hermanas[hermanas.length - 1].id).getBoundingClientRect().top;
      const objetivo = Math.min(maximo, Math.max(minimo, this.arrastre.y - this.arrastre.agarre));

      this.arrastrandoGrupo.forEach((id) => {
        this.filaOrden(id).style.transform = `translateY(${objetivo - natural}px)`;
      });
    },
    finArrastre() {
      if (this.arrastrandoId !== null) {
        cancelAnimationFrame(this.arrastre.cuadro);
        // La fila cae suavemente desde donde se soltó
        this.arrastrandoGrupo.forEach((id) => {
          const el = this.filaOrden(id);
          const desplazamiento = new DOMMatrix(getComputedStyle(el).transform).m42;
          el.style.transform = '';
          if (desplazamiento) this.deslizar(el, desplazamiento);
        });
      }
      this.arrastrandoId = null;
      this.arrastrandoGrupo = [];
      this.arrastre = null;
      window.removeEventListener('pointermove', this.moverArrastre);
      window.removeEventListener('pointerup', this.finArrastre);
      window.removeEventListener('pointercancel', this.finArrastre);
    },
    async guardarOrden() {
      this.guardandoOrden = true;
      try {
        await this.$store.dispatch("categories/reorder", this.ordenArbol.map((c) => c.id));
        this.ordenModal.hide();
        await Swal.fire({ icon: 'success', title: '¡Éxito!', text: 'Orden guardado correctamente.', confirmButtonText: 'Aceptar' });
        this.fetchAll();
      } catch (e) {
        Swal.fire({ icon: 'error', title: 'Error', text: (e && e.data && e.data.message) || 'Error al guardar el orden' });
      } finally {
        this.guardandoOrden = false;
      }
    },
    openForm() {
      this.isEditing = false;
      this.form = { id: 0, code: '', name: '', description: '', parent_id: '' };
      this.showModal();
    },
    editItem(value) {
      this.isEditing = true;
      this.form = { id: value.id, code: value.code || '', name: value.name, description: value.description || '', parent_id: value.parent_id || '' };
      this.showModal();
    },
    showModal() {
      const el = document.getElementById('ModalCategoriaForm');
      this.modalInstance = new bootstrap.Modal(el);
      this.modalInstance.show();
    },
    hideModal() {
      if (this.modalInstance) this.modalInstance.hide();
    },
    cancelEdit() {
      this.isEditing = false;
      this.form = { id: 0, code: '', name: '', description: '', parent_id: '' };
      this.hideModal();
    },
    async submitForm() {
      try {
        const res = await this.$store.dispatch("categories/save", this.form);
        if (res && res.status >= 200 && res.status < 300) {
          this.hideModal();
          await Swal.fire({ icon: 'success', title: '¡Éxito!', text: 'Registro guardado correctamente.', confirmButtonText: 'Aceptar' });
          this.cancelEdit();
          this.fetchData(null);
          this.fetchAll();
        } else throw new Error(res.data.message || 'Error al guardar');
      } catch (e) {
        Swal.fire({ icon: 'error', title: 'Error', text: e.message || 'Error al guardar' });
      }
    },
    async deleteItem(id) {
      try {
        const result = await Swal.fire({
          title: '¿Estás seguro?',
          text: 'Esta acción no se puede deshacer.',
          icon: 'warning',
          showCancelButton: false,
          confirmButtonColor: '#d33',
          confirmButtonText: 'Sí, eliminar!',
        });
        if (result.isConfirmed) {
          const res = await this.$store.dispatch("categories/delete", id);
          if (res && res.status >= 200 && res.status < 300) {
            this.fetchData(null);
            this.fetchAll();
            await Swal.fire('Eliminado!', 'Registro eliminado correctamente.', 'success');
          } else {
            throw new Error(res.data.message || 'Error al eliminar');
          }
        }
      } catch (e) {
        await Swal.fire({ icon: 'error', title: 'Error', text: e.message || 'Error al eliminar, puede tener registros asociados' });
      }
    },
  },
};
</script>

<style scoped>
.orden-fila {
  cursor: grab;
  user-select: none;
}

.orden-fila--grupo {
  background-color: #f0f4ff;
  z-index: 2;
  will-change: transform;
}

.orden-fila--activa {
  cursor: grabbing;
  box-shadow: 0 4px 14px rgba(0, 0, 0, 0.25);
}

/* El ícono captura el gesto táctil en lugar de hacer scroll */
.orden-asa {
  touch-action: none;
}

.pagination {
  display: flex;
  justify-content: center;
  margin-top: 20px;
}

.page-item {
  margin: 0 5px;
}

.active {
  font-weight: bold;
}

.table thead th {
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}

.table tbody td {
  padding-left: 1.5rem;
  padding-right: 1.5rem;
}
</style>
