<template>
  <main class="login-page">
    <div class="login-wrapper">
      <!-- Left Panel -->
      <div class="login-panel login-panel-left">
        <div class="login-mesh-bg"></div>
        <div class="login-particles">
          <span v-for="n in 12" :key="n" :class="`particle particle-${n}`"></span>
        </div>
        <div class="login-logo-left">
          <img src="/assets/Logo.png" alt="MiStock" />
        </div>
        <div class="login-panel-left-content">
          <div class="login-illustration">
            <transition-group name="fade" tag="div" class="illustration-carousel">
              <div
                v-for="(image, index) in carouselImages"
                :key="index"
                v-show="currentImage === index"
                class="illustration-slide"
              >
                <img :src="image.src" :alt="image.alt" />
              </div>
            </transition-group>
          </div>

          <div class="login-carousel-dots">
            <span
              v-for="(image, index) in carouselImages"
