          <div class="login-form-wrapper">
            <div class="login-form-header">
              <h1 class="login-title">Bienvenido</h1>
              <p class="login-subtitle">Ingresa tus credenciales para acceder al sistema</p>
            </div>

            <form role="form" @submit.prevent="handleLogin()">
              <div class="mb-3">
                <label class="login-label">Correo electrónico</label>
                <argon-input
                  v-model="user.email"
                  type="email"
                  class="mb-0"
                  placeholder="nombre@empresa.com"
                  name="email"
                  size="lg"
                  icon="fas fa-envelope"
                  iconDir="left"
                  :value="user.email"
                />
                <validation-error :errors="apiValidationErrors.email" />
              </div>

              <div class="mb-3">
                <label class="login-label">Contraseña</label>
                <argon-input
                  v-model="user.password"
                  type="password"
                  placeholder="••••••••"
                  name="password"
                  size="lg"
                  icon="fas fa-lock"
                  iconDir="left"
                  :value="user.password"
                />
              </div>

              <div class="login-options">
                <argon-switch id="rememberMe" inputClass="login-switch-input" labelClass="login-switch-label">
                  Recuérdame
                </argon-switch>
                <router-link
